\textbf{The Pigeonhole Principle:}
Let $s,k\in\NN$ satisfy $s>k$.  If $s$ objects are placed in $k$ boxes,
then at least one box contains more than one object.

\textbf{Prinsip Sarang Merpati:}
Misalkan $s,k\in\NN$ memenuhi $s>k$. Jika $s$ objek ditempatkan ke dalam $k$
kotak, maka sekurang-kurangnya satu kotak memuat lebih dari satu objek.

Andaikan setiap kotak memuat paling banyak satu objek. Maka terdapat paling
banyak $k$ objek, padahal terdapat $s$ objek dengan $s>k$.
\end{proof}

\textbf{The First Principle of Mathematical Induction:}
Let $S\subset\NN$ be a set satisfying the following two properties:
\begin{enumerate}
\item $1\in S$; and
\item $\forall k\in\NN,\ k\in S\Rightarrow k+1\in S$.
\end{enumerate}
Then $S=\NN$.\newline
More generally, if $\Pp(n)$ is a property of natural numbers which may or
may not be true for any particular $n\in\NN$, satisfying
\begin{enumerate}
\item $\Pp(1)$ is true; and
\item $\forall k\in\NN,\ \Pp(k)\Rightarrow\Pp(k+1)$
\end{enumerate}
then $\forall n\in\NN, \Pp(n)$ is true.

\textbf{Prinsip Pertama Induksi Matematika:}
Misalkan $S\subset\NN$ adalah himpunan yang memenuhi kedua sifat berikut:
\begin{enumerate}
\item $1\in S$; dan
\item $\forall k\in\NN,\ k\in S\Rightarrow k+1\in S$.
\end{enumerate}
Maka $S=\NN$.\newline
Secara lebih umum, misalkan $\Pp(n)$ adalah suatu sifat bilangan asli yang
mungkin benar atau mungkin tidak benar untuk suatu $n\in\NN$ tertentu, dan
memenuhi
\begin{enumerate}
\item $\Pp(1)$ benar; dan
\item $\forall k\in\NN,\ \Pp(k)\Rightarrow\Pp(k+1)$
\end{enumerate}
maka $\forall n\in\NN, \Pp(n)$ benar.

We use mathematical induction to show that $\forall n\in \mathbb{N}$
\begin{equation}
\sum_{j=1}^nj=\frac{n(n+1)}{2}.
\end{equation}
First note that
\begin{equation*}
\sum_{j=1}^1j=1=\frac{1\cdot 2}{2}
\end{equation*}
and thus the the statement is true for $n=1$. For the remaining inductive step, suppose that the formula holds for some particular
$n\in\NN$, that is $\sum_{j=1}^nj=\frac{n(n+1)}{2}$.  We show
that
\begin{equation*}
\sum_{j=1}^{n+1}j=\frac{(n+1)(n+2)}{2}.
\end{equation*}
to complete the proof by induction. Indeed
\begin{equation*}
\sum_{j=1}^{n+1}j=\sum_{j=1}^nj+(n+1)=\frac{n(n+1)}{2}+(n+1)=\frac{(n+1)(n+2)}{2},
\end{equation*}
and the result follows.

Kita menggunakan induksi matematika untuk menunjukkan bahwa
$\forall n\in \mathbb{N}$,
\begin{equation}
\sum_{j=1}^nj=\frac{n(n+1)}{2}.
\end{equation}
Pertama, perhatikan bahwa
\begin{equation*}
\sum_{j=1}^1j=1=\frac{1\cdot 2}{2}
\end{equation*}
sehingga pernyataan tersebut benar untuk $n=1$. Untuk langkah induksi
selanjutnya, andaikan rumus itu berlaku bagi suatu $n\in\NN$ tertentu, yaitu
$\sum_{j=1}^nj=\frac{n(n+1)}{2}$. Kita tunjukkan bahwa
\begin{equation*}
\sum_{j=1}^{n+1}j=\frac{(n+1)(n+2)}{2}.
\end{equation*}
Dengan demikian, bukti induksi akan lengkap. Memang,
\begin{equation*}
\sum_{j=1}^{n+1}j=\sum_{j=1}^nj+(n+1)=\frac{n(n+1)}{2}+(n+1)=\frac{(n+1)(n+2)}{2},
\end{equation*}
dan hasil yang diinginkan pun diperoleh.

Now we use mathematical induction to prove that $n!\leq n^n$ $\forall n\in\NN$.
\index{Principle of Mathematical Induction, first version!used}
\par Note that $1!=1\leq 1^1=1$.  We now present the inductive
step.  Suppose that
\begin{equation*}
n!\leq n^n
\end{equation*}
for some $n\in\NN$, we prove that $(n+1)!\leq (n+1)^{n+1}$. Note that
\begin{equation*}
(n+1)!=(n+1)n!\leq (n+1).n^n<(n+1)(n+1)^{n}=(n+1)^{n+1}.
\end{equation*}
This completes the proof.

Sekarang kita menggunakan induksi matematika untuk membuktikan bahwa
$n!\leq n^n$ untuk setiap $n\in\NN$.
\index{Prinsip Induksi Matematika, versi pertama!digunakan}
\par Perhatikan bahwa $1!=1\leq 1^1=1$. Selanjutnya, kita menyajikan langkah
induksi. Andaikan
\begin{equation*}
n!\leq n^n
\end{equation*}
untuk suatu $n\in\NN$. Kita buktikan bahwa $(n+1)!\leq (n+1)^{n+1}$.
Perhatikan bahwa
\begin{equation*}
(n+1)!=(n+1)n!\leq (n+1)\cdot n^n<(n+1)(n+1)^{n}=(n+1)^{n+1}.
\end{equation*}
Ini melengkapi bukti.

\textbf{The Second Principle of Mathematical Induction:}
\index{Principle of Mathematical Induction, second version!statement}
Let $S\subset\NN$ be a set satisfying the following two properties:
\begin{enumerate}
\item $1\in S$; and
\item $\forall k\in\NN,\ 1,\dots,k\in S\Rightarrow k+1\in S$.
\end{enumerate}
Then $S=\NN$.\newline
More generally, if $\Pp(n)$ is a property of natural numbers which may or
may not be true for any particular $n\in\NN$, satisfying
\begin{enumerate}
\item $\Pp(1)$ is true; and
\item $\forall k\in\NN,$ if $\Pp(1),\dots,\Pp(k)$ are all true, then $\Pp(k+1)$
is also true
\end{enumerate}
then $\forall n\in\NN, \Pp(n)$ is true.

\textbf{Prinsip Kedua Induksi Matematika:}
\index{Prinsip Induksi Matematika, versi kedua!pernyataan}
Misalkan $S\subset\NN$ adalah himpunan yang memenuhi kedua sifat berikut:
\begin{enumerate}
\item $1\in S$; dan
\item $\forall k\in\NN,\ 1,\dots,k\in S\Rightarrow k+1\in S$.
\end{enumerate}
Maka $S=\NN$.\newline
Secara lebih umum, misalkan $\Pp(n)$ adalah suatu sifat bilangan asli yang
mungkin benar atau mungkin tidak benar untuk suatu $n\in\NN$ tertentu, dan
memenuhi
\begin{enumerate}
\item $\Pp(1)$ benar; dan
\item $\forall k\in\NN,$ jika $\Pp(1),\dots,\Pp(k)$ semuanya benar, maka
$\Pp(k+1)$ juga benar,
\end{enumerate}
maka $\forall n\in\NN, \Pp(n)$ benar.

\begin{enumerate}
\item \textbf{Commutativity of addition and multiplication}\index{commutativity of addition and multiplication}
\begin{align*}
\forall a,b\in\ZZ:\quad a+b&=b+a\\
a\cdot b&=b\cdot a
\end{align*}
\item \textbf{Associativity of addition and multiplication}\index{associativity of addition and multiplication}
\begin{align*}
\forall a,b,c\in\ZZ:\quad (a+b)+c&=a+(b+c)\\
(a\cdot b)\cdot c&= a\cdot (b\cdot c)
\end{align*}
\item \textbf{Distributivity of multiplication over addition}\index{distributivity of multiplication over addition}
$$
\forall a,b,c\in\ZZ:\quad a\cdot (b+c)=a\cdot b+a\cdot c.\hskip2cm\ 
$$
\end{enumerate}

\begin{enumerate}
\item \textbf{Komutativitas penjumlahan dan perkalian}\index{komutativitas penjumlahan dan perkalian}
\begin{align*}
\forall a,b\in\ZZ:\quad a+b&=b+a\\
a\cdot b&=b\cdot a
\end{align*}
\item \textbf{Asosiativitas penjumlahan dan perkalian}\index{asosiativitas penjumlahan dan perkalian}
\begin{align*}
\forall a,b,c\in\ZZ:\quad (a+b)+c&=a+(b+c)\\
(a\cdot b)\cdot c&= a\cdot (b\cdot c)
\end{align*}
\item \textbf{Distributivitas perkalian terhadap penjumlahan}\index{distributivitas perkalian terhadap penjumlahan}
$$
\forall a,b,c\in\ZZ:\quad a\cdot (b+c)=a\cdot b+a\cdot c.\hskip2cm\ 
$$
\end{enumerate}

The set $\ZZ$ allows {\bf additive inverses}\index{additive inverse} for its
elements, in the sense that for every $a\in\ZZ$ there exists
another integer in $\ZZ$, denoted by $-a$, such that
\begin{equation}
a+(-a)=0.
\end{equation}

Setiap elemen dalam himpunan $\ZZ$ mempunyai {\bf invers
aditif}\index{invers aditif}. Artinya, untuk setiap $a\in\ZZ$ terdapat bilangan
bulat lain dalam $\ZZ$, yang dinotasikan dengan $-a$, sedemikian sehingga
\begin{equation}
a+(-a)=0.
\end{equation}

\begin{discussion}
We now discuss the concept of divisibility and its properties.
\end{discussion}

\begin{discussion}
Sekarang kita membahas konsep keterbagian beserta sifat-sifatnya.
\end{discussion}

\begin{example}
For example, $2\mid 4$ and $7\mid 63$, while $5\nmid 26$.
\end{example}

\begin{example}
Sebagai contoh, $2\mid 4$ dan $7\mid 63$, sedangkan $5\nmid 26$.
\end{example}

\begin{definition}\index{even integer}\index{odd integer}
Given $a\in\ZZ$, we say $a$ is {\bf even} if $2\mid a$, \emph{i.e.,}
if $\exists k\in\ZZ$ s.t.\ $a=2k$.  In contrast, given $a\in\ZZ$, we say $a$
is {\bf odd} if $2\nmid a$.
\end{definition}

\begin{definition}\index{bilangan bulat genap}\index{bilangan bulat ganjil}
Untuk $a\in\ZZ$, kita mengatakan bahwa $a$ adalah bilangan {\bf genap} jika
$2\mid a$, yaitu jika $\exists k\in\ZZ$ sedemikian sehingga $a=2k$. Sebaliknya,
untuk $a\in\ZZ$, kita mengatakan bahwa $a$ adalah bilangan {\bf ganjil} jika
$2\nmid a$.
\end{definition}

\begin{discussion}
It is a consequence of the Division Algorithm,\index{Division Algorithm!used}
below, that if $a$ is odd then $\exists k\in\ZZ$ s.t.\ $a=2k+1$.
\end{discussion}

\begin{discussion}
Sebagai konsekuensi dari Algoritma Pembagian\index{Algoritma Pembagian!digunakan}
di bawah ini, jika $a$ ganjil maka $\exists k\in\ZZ$ sedemikian sehingga
$a=2k+1$.
\end{discussion}

\begin{proposition} Untuk $a,b\in\ZZ$ dengan $a\neq 0$, berlaku
$a\mid b\Leftrightarrow a\mid|b|$.
\end{proposition}

\begin{theorem}\index{divisibility!transitivity}
If $a, b$ and $c$ are integers such that $a\mid b$ and $b\mid c$,
then $a\mid c$.
\end{theorem}

\begin{theorem}\index{keterbagian!transitivitas}
Jika $a$, $b$, dan $c$ adalah bilangan bulat yang memenuhi $a\mid b$ dan
$b\mid c$, maka $a\mid c$.
\end{theorem}

\begin{proof}
Since $a\mid b$ and $b\mid c$, we know $\exists k_1, k_2\in\ZZ$ such that
$b=k_1a$ and $c=k_2b$.  Hence $c=k_1k_2a$ and so $a\mid c$.
\end{proof}

\begin{proof}
Karena $a\mid b$ dan $b\mid c$, terdapat $k_1,k_2\in\ZZ$ sedemikian sehingga
$b=k_1a$ dan $c=k_2b$. Oleh karena itu, $c=k_1k_2a$, sehingga $a\mid c$.
\end{proof}

\begin{example}\label{eg:divisibility}
Since $6\mid 18$ and $18\mid 36$, then $6\mid 36$.
\end{example}

\begin{example}\label{eg:divisibility}
Karena $6\mid 18$ dan $18\mid 36$, maka $6\mid 36$.
\end{example}

\begin{discussion}
The following theorem states that if an integer divides two other
integers then it divides any linear combination of these integers.
\end{discussion}

\begin{discussion}
Teorema berikut menyatakan bahwa jika suatu bilangan bulat membagi dua bilangan
bulat lain, bilangan tersebut juga membagi setiap kombinasi linear keduanya.
\end{discussion}

\begin{theorem}\label{thm:divisibilitylincombs}\index{divisibility!of linear combinations}
$\forall a,b,c,m,n\in\ZZ$, if $c\mid a$ and $c\mid b$ then $c\mid (ma+nb)$.
\end{theorem}

\begin{theorem}\label{thm:divisibilitylincombs}\index{keterbagian!kombinasi linear}
Untuk setiap $a,b,c,m,n\in\ZZ$, jika $c\mid a$ dan $c\mid b$, maka
$c\mid (ma+nb)$.
\end{theorem}

\begin{proof}
Since $c\mid a$ and $c\mid b$, $\exists k_1, k_2\in\ZZ$ such that $a=k_1c$ and
$b=k_2c$. Thus
\begin{equation*}
ma+nb=mk_1c+nk_2c=c(mk_1+nk_2),
\end{equation*}
and hence $c\mid (ma+nb)$.
\end{proof}

\begin{proof}
Karena $c\mid a$ dan $c\mid b$, terdapat $k_1,k_2\in\ZZ$ sedemikian sehingga
$a=k_1c$ dan $b=k_2c$. Dengan demikian,
\begin{equation*}
ma+nb=mk_1c+nk_2c=c(mk_1+nk_2),
\end{equation*}
dan karena itu $c\mid (ma+nb)$.
\end{proof}

\begin{discussion}
Theorem~\ref{thm:divisibilitylincombs} can be generalized to any finite linear
combination as follows. If
\begin{equation*}\index{divisibility!of linear combinations}
n\in\NN,\ a,b_1,\dots,b_n\in\ZZ\text{\ and\ }a\mid b_1, a\mid b_2,\dots,a\mid b_n
\end{equation*}
then
\begin{equation}
a\mid \sum_{j=1}^nk_jb_j
\end{equation}
$\forall k_1,\dots,k_n\in\ZZ$. It would be a nice exercise to prove this
generalization by induction.
\end{discussion}

\begin{discussion}
Teorema~\ref{thm:divisibilitylincombs} dapat diperumum ke setiap kombinasi
linear berhingga sebagai berikut. Jika
\begin{equation*}\index{keterbagian!kombinasi linear}
n\in\NN,\ a,b_1,\dots,b_n\in\ZZ\text{\ dan\ }a\mid b_1, a\mid b_2,\dots,a\mid b_n,
\end{equation*}
maka, untuk setiap $k_1,\dots,k_n\in\ZZ$,
\begin{equation}
a\mid \sum_{j=1}^nk_jb_j
\end{equation}
Pembuktian perumuman ini dengan induksi merupakan latihan yang baik.
\end{discussion}

\begin{theorem}\label{thm:theDA}\index{Division Algorithm!statement}
\textbf{The Division Algorithm} Given $a,b\in\ZZ$ such that $b>0$, there exist unique $q,r\in\ZZ$
such that $a=qb+r$ and $0\leq r< b$.  This $q$ is called the
{\bf quotient}\index{quotient}
and $r$ the
{\bf remainder when $a$ is divided by $b$}.\index{remainder!definition}
\end{theorem}

\begin{theorem}\label{thm:theDA}\index{Algoritma Pembagian!pernyataan}
\textbf{Algoritma Pembagian} Diberikan $a,b\in\ZZ$ dengan $b>0$, terdapat
pasangan tunggal $q,r\in\ZZ$ sedemikian sehingga $a=qb+r$ dan $0\leq r<b$.
Bilangan $q$ disebut {\bf hasil bagi}\index{hasil bagi}, sedangkan $r$ disebut
{\bf sisa pembagian $a$ oleh $b$}.\index{sisa pembagian!definisi}
\end{theorem}

\begin{proof}
Consider the set $A=\{a-bk\geq 0 \mid k\in \ZZ\}$.  Note that
$A$ is nonempty since for $k<a/b$, $a-bk>0$.  By the well-ordering
principle,\index{Well-Ordering Principle!used} $A$ has a least element
$r=a-qb$ for some $q\in\ZZ$. Notice that $r\geq 0$ by construction.  Now if
$r\geq b$ then (since $b>0$)
\begin{equation*}
r>r-b=a-qb-b=a-(q+1)b\geq 0.
\end{equation*}
This leads to a contradiction since $r$ is assumed to be the least
positive integer of the form $r=a-qb$.  As a result we have $0\leq r<b$.
\par We will show that $q$ and $r$ are unique.  Suppose
that $a=q_1b+r_1$ and $a=q_2b+r_2$ with $0\leq r_1<b$ and $0\leq r_2<b$.  Then we
have
\begin{equation*}
a-a=q_1b+r_1-(q_2b+r_2)=(q_1-q_2)b+(r_1-r_2)=0.
\end{equation*}
As a result we have
\begin{equation*}
(q_1-q_2)b=r_2-r_1.
\end{equation*}
Thus we get that
\begin{equation*}
b\mid (r_2-r_1).
\end{equation*}
And since $-\max(r_1,r_2)\leq|r_2-r_1|\leq\max(r_1,r_2)$, and $b>\max(r_1,r_2)$,
then $r_2-r_1$ must be $0$, i.e. $r_2=r_1$. And since
$bq_1+r_1=bq_2+r_2$, we also get that $q_1=q_2$. This proves uniqueness.
\end{proof}

\begin{proof}
Perhatikan himpunan $A=\{a-bk\mid k\in\ZZ,\ a-bk\geq 0\}$. Himpunan $A$
tidak kosong karena untuk $k<a/b$ berlaku $a-bk>0$. Menurut prinsip
keterurutan baik\index{Prinsip Keterurutan Baik!digunakan}, $A$ memiliki elemen
terkecil $r=a-qb$ untuk suatu $q\in\ZZ$. Berdasarkan konstruksinya, $r\geq 0$.
Sekarang, jika $r\geq b$, maka (karena $b>0$)
\begin{equation*}
r>r-b=a-qb-b=a-(q+1)b\geq 0.
\end{equation*}
Hal ini menghasilkan kontradiksi karena $r$ diasumsikan sebagai elemen terkecil
$A$. Oleh karena itu, $0\leq r<b$.
\par Selanjutnya kita tunjukkan bahwa $q$ dan $r$ tunggal. Misalkan
$a=q_1b+r_1$ dan $a=q_2b+r_2$, dengan $0\leq r_1<b$ dan $0\leq r_2<b$. Maka
\begin{equation*}
a-a=q_1b+r_1-(q_2b+r_2)=(q_1-q_2)b+(r_1-r_2)=0.
\end{equation*}
Akibatnya,
\begin{equation*}
(q_1-q_2)b=r_2-r_1.
\end{equation*}
Jadi,
\begin{equation*}
b\mid (r_2-r_1).
\end{equation*}
Karena $0\leq|r_2-r_1|\leq\max(r_1,r_2)$ dan $b>\max(r_1,r_2)$, maka
$r_2-r_1$ harus sama dengan $0$, yaitu $r_2=r_1$. Karena
$bq_1+r_1=bq_2+r_2$, kita juga memperoleh $q_1=q_2$. Hal ini membuktikan
ketunggalan.
\end{proof}

\begin{example}\label{eg:arithmetic}
If $a=71$ and $b=6$, then $71=6\cdot 11+5$.  Here $q=11$ and $r=5$.
\end{example}

\begin{example}\label{eg:arithmetic}
Jika $a=71$ dan $b=6$, maka $71=6\cdot 11+5$. Di sini $q=11$ dan $r=5$.
\end{example}

\begin{exercise}
Show that $5\mid 25, 19\mid38$ and $2\mid 98$.
\end{exercise}

\begin{exercise}
Tunjukkan bahwa $5\mid 25$, $19\mid38$, dan $2\mid 98$.
\end{exercise}

\begin{exercise}
Use the division algorithm to find the quotient and the remainder when 76 is
divided by 13.
\end{exercise}

\begin{exercise}
Gunakan Algoritma Pembagian untuk menentukan hasil bagi dan sisa ketika 76
dibagi oleh 13.
\end{exercise}

\begin{exercise}
Use the division algorithm to find the quotient and the remainder when -100
is divided by 13.
\end{exercise}

\begin{exercise}
Gunakan Algoritma Pembagian untuk menentukan hasil bagi dan sisa ketika -100
dibagi oleh 13.
\end{exercise}

\begin{exercise}
Show that if $a,b,c$ and $d$ are integers with $a$ and $c$ nonzero, such that
$a\mid b$ and $c\mid d$, then $ac\mid bd$.
\end{exercise}

\begin{exercise}
Tunjukkan bahwa jika $a,b,c$, dan $d$ adalah bilangan bulat, dengan $a$ dan $c$
tidak nol, serta $a\mid b$ dan $c\mid d$, maka $ac\mid bd$.
\end{exercise}

\begin{exercise}\label{exer:sizeofdivisors}
Show that if $a$ and $b$ are positive integers and $a\mid b$, then $a\leq b$.
\end{exercise}

\begin{exercise}\label{exer:sizeofdivisors}
Tunjukkan bahwa jika $a$ dan $b$ adalah bilangan bulat positif dan $a\mid b$,
maka $a\leq b$.
\end{exercise}

\begin{exercise}
Prove that the sum of two even integers is even, the sum of two odd integers
is even and the sum of an even integer and an odd integer is odd.
\end{exercise}

\begin{exercise}
Buktikan bahwa jumlah dua bilangan bulat genap adalah genap, jumlah dua bilangan
bulat ganjil adalah genap, dan jumlah sebuah bilangan bulat genap dengan sebuah
bilangan bulat ganjil adalah ganjil.
\end{exercise}

\begin{exercise}
Show that the product of two even integers is even, the product of two odd
integers is odd and the product of an even integer and an odd integer is even.
\end{exercise}

\begin{exercise}
Tunjukkan bahwa hasil kali dua bilangan bulat genap adalah genap, hasil kali dua
bilangan bulat ganjil adalah ganjil, dan hasil kali sebuah bilangan bulat genap
dengan sebuah bilangan bulat ganjil adalah genap.
\end{exercise}

\begin{exercise}
Show that if $m$ is an integer then $3$ divides $m^3-m$.
\end{exercise}

\begin{exercise}
Tunjukkan bahwa jika $m$ adalah bilangan bulat, maka $3$ membagi $m^3-m$.
\end{exercise}

\begin{exercise}
Show that the square of every odd integer is of the form $8m+1$.
\end{exercise}

\begin{exercise}
Tunjukkan bahwa kuadrat setiap bilangan bulat ganjil berbentuk $8m+1$ untuk
suatu $m\in\ZZ$.
\end{exercise}

\begin{exercise}
Show that the square of any integer is of the form $3m$ or $3m+1$ but not of the
form $3m+2$.
\end{exercise}

\begin{exercise}
Tunjukkan bahwa untuk setiap bilangan bulat $n$, kuadrat $n$ berbentuk $3m$
atau $3m+1$ untuk suatu $m\in\ZZ$, tetapi tidak pernah berbentuk $3m+2$ untuk
$m\in\ZZ$.
\end{exercise}

\begin{exercise}
Show that if $ac\mid bc$, then $a\mid b$.
\end{exercise}

\begin{exercise}
Tunjukkan bahwa jika $ac\mid bc$, maka $a\mid b$.
\end{exercise}

\begin{exercise}
Show that if $a\mid b$ and $b\mid a$ then $a=\pm b$.
\end{exercise}

\begin{exercise}
Tunjukkan bahwa jika $a\mid b$ dan $b\mid a$, maka $a=\pm b$.
\end{exercise}

\begin{theorem}\label{thm:basebexpansion}
Let $b\in\ZZ$ satisfy $b>1$.  Then $\forall m\in\NN$, $\exists l\in\NN$ and
$\exists a_1,\dots,a_l\in\ZZ$ such that
\begin{align*}
m=a_lb^l+a_{l-1}b^{l-1}+\dots+a_1b+a_0,\\
0\leq a_j<b\text{\ for\ }j=0,1,\dots,l,\text{\ and}\ \ \ \\
a_l\neq 0.\hskip2.5cm
\end{align*}
\end{theorem}

\begin{theorem}\label{thm:basebexpansion}
Misalkan $b\in\ZZ$ memenuhi $b>1$. Maka, untuk setiap $m\in\NN$, terdapat
tepat satu $l\in\ZZ_{\geq 0}$ beserta digit-digit $a_0,a_1,\dots,a_l\in\ZZ$
sedemikian sehingga
\begin{align*}
m=\sum_{j=0}^{l}a_jb^j,\\
0\leq a_j<b\text{\ untuk\ }j=0,1,\dots,l,\text{\ dan}\ \ \ \\
a_l\neq 0.\hskip2.5cm
\end{align*}
\end{theorem}

\begin{proof}
Fix an $m\in\NN$.  We start by dividing $m$ by
$b$\index{Division Algorithm!used} and we get
\begin{equation*}
m=q_0b+a_0, \ \ \ 0\leq a_0 <b.
\end{equation*}
If $q_0\neq 0$ then we continue to divide $q_0$ by $b$ and we get
\begin{equation*}
q_0=q_1b+a_1, \ \ \ 0\leq a_1<b.
\end{equation*}
We continue this process and hence we get
\begin{align*}
q_1&=q_2b+a_2, \ \ \  0\leq a_2<b,\\
&\ .\\
&\ .\\
&\ .\\
q_{l-2}&=q_{l-1}b+a_{l-1}, \ \ \ 0\leq a_{l-1}<b,\\
q_{l-1}&=0\cdot b+a_l, \ \ \ 0\leq a_l<b.
\end{align*}
Note that the sequence $q_0,q_1,\dots$ is a decreasing sequence of
non-negative integers with a last term $q_l$ that must be 0.
\par Now substituting the equation $q_0=q_1b+a_1$ in $m=q_0b+a_0$, we get
\begin{equation*}
m=(q_1b+a_1)b+a_0=q_1b^2+a_1b+a_0,
\end{equation*}
Successively substituting the equations in $m$, we get
\begin{align*}
m&=q_2b^3+a_2b^2+a_1b+a_0,\\
&\ .\\
&\ .\\
&\ .\\
&=q_{l-1}b^l+a_{l-1}b^{l-1}+\dots+a_1b+a_0,\\
&= a_lb^l+a_{l-1}b^{l-1}+\dots+a_1b+a_0.
\end{align*}
What remains to prove is that the representation is unique. Suppose
now that
\begin{equation*}
m=a_lb^l+a_{l-1}b^{l-1}+\dots+a_1b+a_0=c_lb^l+c_{l-1}b^{l-1}+\dots+c_1b+c_0
\end{equation*}
where if the number of terms is different in one expansion, we add
zero coefficients to make the number of terms agree.  Subtracting
the two expansions, we get
\begin{equation*}
(a_l-c_l)b^l+(a_{l-1}-c_{l-1})b^{l-1}+\dots+(a_1-c_1)b+(a_0-c_0)=0.
\end{equation*}
If the two expansions are different, then there exists $0\leq j\leq
l$ such that $c_j\neq a_j$.  As a result, we get
\begin{equation*}
b^j((a_l-c_l)b^{l-j}+\dots+(a_{j+1}-c_{j+1})b+(a_j-c_j))=0
\end{equation*}
and since $b\neq 0$, we get
\begin{equation*}
(a_l-c_l)b^{l-j}+\dots+(a_{j+1}-c_{j+1})b+(a_j-c_j)=0.
\end{equation*}
We now get
\begin{equation*}
 a_j-c_j=(a_l-c_l)b^{l-j}+\dots+(a_{j+1}-c_{j+1})b,
\end{equation*}
and as a result, $b\mid (a_j-c_j)$.  Since $0\leq a_j<b$ and $0\leq
c_j<b$, we get that $a_j=c_j$.  This is a contradiction and hence
the expansion is unique.
\end{proof}

\begin{proof}
Ambil sebarang $m\in\NN$. Mula-mula kita membagi $m$ dengan
$b$ menggunakan Algoritma Pembagian\index{Algoritma Pembagian!digunakan},
sehingga diperoleh
\begin{equation*}
m=q_0b+a_0, \ \ \ 0\leq a_0 <b.
\end{equation*}
Jika $q_0\neq 0$, selanjutnya kita membagi $q_0$ dengan $b$ dan memperoleh
\begin{equation*}
q_0=q_1b+a_1, \ \ \ 0\leq a_1<b.
\end{equation*}
Jika $q_0=0$, ambil $l=0$ dan $a_0=m$; bagian eksistensi selesai. Selanjutnya,
anggap $q_0>0$. Karena setiap hasil bagi positif berikutnya lebih kecil daripada
hasil bagi sebelumnya, untuk suatu $l\geq1$ proses ini pertama kali berakhir
pada $q_l=0$. Dengan demikian,
\begin{align*}
q_{j-1}&=q_jb+a_j, \qquad 0\leq a_j<b \quad (j=1,\dots,l),\\
q_l&=0, \qquad a_l=q_{l-1}\neq0.
\end{align*}
\par Sekarang, dengan menyubstitusikan persamaan $q_0=q_1b+a_1$ ke dalam
$m=q_0b+a_0$, diperoleh
\begin{equation*}
m=(q_1b+a_1)b+a_0=q_1b^2+a_1b+a_0.
\end{equation*}
Dengan menyubstitusikan persamaan-persamaan tersebut secara berturut-turut
(atau dengan induksi pada $j$), diperoleh
\begin{align*}
m&=q_{j-1}b^j+\sum_{i=0}^{j-1}a_ib^i \qquad (j=1,\dots,l),\\
 &=a_lb^l+\sum_{i=0}^{l-1}a_ib^i
 =\sum_{i=0}^{l}a_ib^i.
\end{align*}
Yang masih harus dibuktikan ialah bahwa representasi tersebut tunggal. Sekarang
misalkan
\begin{equation*}
m=\sum_{i=0}^{l}a_ib^i=\sum_{i=0}^{s}c_ib^i.
\end{equation*}
Ambil $L=\max\{l,s\}$ dan tambahkan koefisien nol pada ekspansi yang lebih
pendek. Dengan mengurangkan kedua ekspansi tersebut, diperoleh
\begin{equation*}
\sum_{i=0}^{L}(a_i-c_i)b^i=0.
\end{equation*}
Jika kedua ekspansi berbeda, ambil indeks terkecil $0\leq j\leq L$ sedemikian
sehingga $c_j\neq a_j$. Semua suku berindeks lebih kecil daripada $j$ lenyap,
sehingga diperoleh
\begin{equation*}
b^j\sum_{i=j}^{L}(a_i-c_i)b^{i-j}=0,
\end{equation*}
dan karena $b\neq 0$, diperoleh
\begin{equation*}
\sum_{i=j}^{L}(a_i-c_i)b^{i-j}=0.
\end{equation*}
Oleh karena itu,
\begin{equation*}
a_j-c_j=-b\sum_{i=j+1}^{L}(a_i-c_i)b^{i-j-1},
\end{equation*}
sehingga $b\mid (a_j-c_j)$. Karena $0\leq a_j<b$ dan $0\leq c_j<b$,
berlaku $|a_j-c_j|<b$. Dengan demikian, $a_j=c_j$. Ini bertentangan dengan
pemilihan $j$, sehingga ekspansi tersebut tunggal.
\end{proof}

\begin{example}\label{eg:basetwo}
To find the expansion of 214 base 3:
we do the following
\begin{align*}
214&=3\cdot 71+1\\
71&= 3\cdot 23+2\\
23&= 3\cdot 7+2\\
7&= 3\cdot 2+1\\
2&= 3\cdot 0+2\\
\end{align*}
As a result, to obtain a base 3 expansion of 214, we take the
remainders of divisions and we get that $(214)_{10}=(21221)_3$.
\end{example}

\begin{example}\label{eg:basetwo}
Untuk mencari ekspansi basis 3 dari 214, kita melakukan pembagian berikut:
\begin{align*}
214&=3\cdot 71+1\\
71&= 3\cdot 23+2\\
23&= 3\cdot 7+2\\
7&= 3\cdot 2+1\\
2&= 3\cdot 0+2\\
\end{align*}
Untuk memperoleh ekspansi basis 3 dari 214, kita membaca sisa-sisa pembagian
tersebut dari bawah ke atas, sehingga $(214)_{10}=(21221)_3$.
\end{example}

\begin{example}\label{eg:changebase}
To find the base $10$ expansion, {\it i.e.,} the decimal expansion, of
$(364)_7$:
We do the following: $4\cdot 7^0+6\cdot 7^1+3\cdot 7^2=4+42+147=193$.
\end{example}

\begin{example}\label{eg:changebase}
Untuk mencari ekspansi basis $10$, yaitu ekspansi desimal, dari $(364)_7$, kita
menghitung $4\cdot 7^0+6\cdot 7^1+3\cdot 7^2=4+42+147=193$.
\end{example}

