\begin{definition}\index{greatest common divisor!definition}
Given $a,b\in\ZZ$, not both zero, the {\bf greatest common divisor} 
is the largest integer that divides both $a$ and $b$, and is written
$\gcd(a,b)$ (or sometimes just $(a,b)$).

When it makes some formul\ae\ simpler, we will write $\gcd(0,0)=0$.
\end{definition}

\begin{definition}\index{faktor persekutuan terbesar!definisi}
Untuk $a,b\in\ZZ$ yang tidak keduanya nol, {\bf faktor persekutuan
terbesar} adalah bilangan bulat terbesar yang membagi $a$ sekaligus $b$, dan
ditulis $\gcd(a,b)$ (atau kadang-kadang cukup $(a,b)$).

Jika hal ini menyederhanakan suatu rumus, kita menetapkan $\gcd(0,0)=0$.
\end{definition}

\begin{example}\label{eg:gcda}\index{greatest common divisor!examples}
The greatest common divisor of 24 and 18 is 6.  In other words $\gcd(24,18)=6$.
\end{example}

\begin{example}\label{eg:gcda}\index{faktor persekutuan terbesar!contoh}
Faktor persekutuan terbesar dari 24 dan 18 adalah 6. Dengan kata lain,
$\gcd(24,18)=6$.
\end{example}

\begin{definition}\index{relatively prime!definition}
$a,b\in\ZZ$ are said to be {\bf relatively prime} if $\gcd(a,b)=1$.
\index{greatest common divisor!used}
\end{definition}

\begin{definition}\index{relatif prima!definisi}
Bilangan $a,b\in\ZZ$ disebut {\bf relatif prima} jika $\gcd(a,b)=1$.
\index{faktor persekutuan terbesar!digunakan}
\end{definition}

\begin{example}\label{eg:gcdb}
The greatest common divisor of 9 and 16 is 1, thus they are
relatively prime.
\end{example}

\begin{example}\label{eg:gcdb}
Faktor persekutuan terbesar dari 9 dan 16 adalah 1; jadi, kedua bilangan
tersebut relatif prima.
\end{example}

\begin{discussion}
Note that every integer has positive and negative divisors.  If
$a$ is a positive divisor of $m$, then $-a$ is also a divisor of
$m$.  Therefore by our definition of the greatest common divisor, we
can see that $\gcd(a,b)=\gcd(|a|, |b|)$.
\index{greatest common divisor!properties}

We can use the gcd of two integers to make relatively prime integers:
\end{discussion}

\begin{discussion}
Perhatikan bahwa setiap bilangan bulat mempunyai pembagi positif dan negatif.
Jika $a$ adalah pembagi positif dari $m$, maka $-a$ juga merupakan pembagi dari
$m$. Karena itu, dari definisi faktor persekutuan terbesar terlihat bahwa
$\gcd(a,b)=\gcd(|a|, |b|)$.
\index{faktor persekutuan terbesar!sifat}

Kita dapat menggunakan FPB dua bilangan bulat untuk membentuk bilangan-bilangan
yang relatif prima:
\end{discussion}

\begin{theorem}\label{thm:dividebygcd}\index{relatively prime}
If $a,b\in\ZZ$ have $\gcd(a,b)=d$ then $\gcd(a/d,b/d)=1$.
\index{greatest common divisor!used}
\end{theorem}

\begin{theorem}\label{thm:dividebygcd}\index{relatif prima}
Jika $a,b\in\ZZ$ tidak keduanya nol dan $\gcd(a,b)=d$, maka
\\
$\gcd(a/d,b/d)=1$.
\index{faktor persekutuan terbesar!digunakan}
\end{theorem}

\begin{proof}
Fix $a,b\in\ZZ$.  We will show that $a/d$ and $b/d$ have no common positive
divisors other than $1$. Let $k\in\NN$ be a divisor of both $a/d$ and $b/d$,
so $\exists m,n\in\NN$ such that
\begin{equation*}
a/d=km \hspace{0.3 cm}\mbox{and} \ \  b/d=kn
\end{equation*}
Thus we get that
\begin{equation*}
a=kmd \hspace{0.3 cm}\mbox{and} \ \  b=knd.
\end{equation*}
Hence $kd$ is a common divisor of both $a$ and $b$.  Also,
$kd\geq d$. However, $d$ is the greatest common divisor of $a$ and
$b$.  As a result, we get that $k=1$.
\end{proof}

\begin{proof}
Ambil $a,b\in\ZZ$. Kita akan menunjukkan bahwa $a/d$ dan $b/d$ tidak
mempunyai pembagi bersama positif selain $1$. Misalkan $k\in\NN$ membagi
$a/d$ sekaligus $b/d$. Maka $\exists m,n\in\ZZ$ sedemikian sehingga
\begin{equation*}
a/d=km \hspace{0.3 cm}\mbox{dan} \ \  b/d=kn
\end{equation*}
Dengan demikian,
\begin{equation*}
a=kmd \hspace{0.3 cm}\mbox{dan} \ \  b=knd.
\end{equation*}
Jadi, $kd$ merupakan pembagi bersama dari $a$ dan $b$. Selain itu,
$kd\geq d$. Namun, $d$ adalah faktor persekutuan terbesar dari $a$ dan $b$,
sehingga $kd\leq d$. Oleh karena itu, $k=1$.
\end{proof}

\begin{discussion}
The next theorem shows that the greatest common divisor of two
integers does not change when we add a multiple of one of the
two integers to the other.
\end{discussion}

\begin{discussion}
Teorema berikut menunjukkan bahwa faktor persekutuan terbesar dari dua bilangan
bulat tidak berubah ketika suatu kelipatan dari salah satunya ditambahkan pada
bilangan yang lain.
\end{discussion}

\begin{theorem}\index{greatest common divisor!properties}
Let $a,b,c\in\ZZ$.  Then $\gcd(a,b)=\gcd(a+cb,b)$.
\end{theorem}

\begin{theorem}\index{faktor persekutuan terbesar!sifat}
Misalkan $a,b,c\in\ZZ$. Maka $\gcd(a,b)=\gcd(a+cb,b)$.
\end{theorem}

\begin{example}\label{eg:gcdc}\index{greatest common divisor!examples}
Notice that $\gcd(4,14)=\gcd(4,14-3\cdot 4)=\gcd(4,2)=2$.
\end{example}

\begin{example}\label{eg:gcdc}\index{faktor persekutuan terbesar!contoh}
Perhatikan bahwa $\gcd(4,14)=\gcd(4,14-3\cdot 4)=\gcd(4,2)=2$.
\end{example}

\begin{discussion}
We now present a theorem which proves that the greatest common
divisor of two integers can be written as a linear combination of
the two integers.
\end{discussion}

\begin{discussion}
Sekarang kita menyajikan teorema yang membuktikan bahwa faktor persekutuan
terbesar dari dua bilangan bulat dapat ditulis sebagai kombinasi linear dari
kedua bilangan tersebut.
\end{discussion}

\begin{theorem}\label{thm:gcdislincomb}
\index{greatest common divisor!properties}
Let $a,b\in\ZZ$ not both be zero.  Then $\gcd(a,b)$ is the smallest natural
number which is of the form $d=ma+nb$ for some $m,n\in\ZZ$.
\end{theorem}

\begin{theorem}\label{thm:gcdislincomb}
\index{faktor persekutuan terbesar!sifat}
Misalkan $a,b\in\ZZ$ tidak keduanya nol. Maka $\gcd(a,b)$ adalah bilangan
asli terkecil yang berbentuk $d=ma+nb$ untuk suatu $m,n\in\ZZ$.
\end{theorem}

\begin{discussion}
There is a simple application of this which will be very useful in the future:
\end{discussion}

\begin{discussion}
Berikut suatu penerapan sederhana yang akan sangat berguna kelak:
\end{discussion}

\begin{corollary}\label{cor:intlincombrelprime}\index{relatively prime!linear combination giving $1$}
If $a,b\in\ZZ$ are relatively prime, then $\exists m,n\in\ZZ$ such that
$ma+nb=1$.
\end{corollary}

\begin{corollary}\label{cor:intlincombrelprime}\index{relatif prima!kombinasi linear yang menghasilkan $1$}
Jika $a,b\in\ZZ$ relatif prima, maka $\exists m,n\in\ZZ$ sedemikian sehingga
$ma+nb=1$.
\end{corollary}

\begin{definition}\index{greatest common divisor!definition for more than two integers}
For some $n\in\NN$, let $a_1,a_2,\dots,a_n\in\ZZ$ not be all $0$.  The
{\bf greatest common divisor} of these integers is the largest integer that
divides all of them, and is denoted $\gcd(a_1,\dots,a_n)$.
\end{definition}

\begin{definition}\index{faktor persekutuan terbesar!definisi untuk lebih dari dua bilangan bulat}
Untuk suatu $n\in\NN$, misalkan $a_1,a_2,\dots,a_n\in\ZZ$ tidak semuanya
$0$. {\bf Faktor persekutuan terbesar} dari bilangan-bilangan tersebut adalah
bilangan bulat terbesar yang membagi semuanya, dan dilambangkan dengan
$\gcd(a_1,\dots,a_n)$.
\end{definition}

\begin{definition}\index{mutually relatively prime}
For some $n\in\NN$, $a_1,a_2,\dots,a_n\in\ZZ$ are said to be
{\bf mutually relatively prime} if $\gcd(a_1,a_2,\dots,a_n)=1$.
\index{greatest common divisor!used}
\end{definition}

\begin{definition}\index{relatif prima secara bersama-sama}
Untuk suatu $n\in\NN$, bilangan-bilangan $a_1,a_2,\dots,a_n\in\ZZ$
disebut {\bf relatif prima secara bersama-sama} jika
$\gcd(a_1,a_2,\dots,a_n)=1$.
\index{faktor persekutuan terbesar!digunakan}
\end{definition}

\begin{example}\label{eg:mutrelprime}
The integers $3, 6, 7$ are mutually relatively prime since
$(3,6,7)=1$ although $(3,6)=3$.
\end{example}

\begin{example}\label{eg:mutrelprime}
Bilangan-bilangan bulat $3, 6, 7$ relatif prima secara bersama-sama karena
$(3,6,7)=1$, meskipun $(3,6)=3$.
\end{example}

\begin{definition}\index{pairwise relatively prime!definition}
For some $n\in\NN$, $a_1,a_2,\dots,a_n\in\ZZ$ are called
{\bf pairwise relatively prime} if $\forall i,j\in\NN$ such that $i\le n$,
$j\le n$, and $i\neq j$, we have $\gcd(a_i,a_j)=1$.
\index{greatest common divisor!used}
\end{definition}

\begin{definition}\index{relatif prima berpasangan!definisi}
Untuk suatu $n\in\NN$, bilangan-bilangan $a_1,a_2,\dots,a_n\in\ZZ$
disebut {\bf relatif prima berpasangan} jika $\forall i,j\in\NN$ dengan
$i\le n$, $j\le n$, dan $i\neq j$, berlaku $\gcd(a_i,a_j)=1$.
\index{faktor persekutuan terbesar!digunakan}
\end{definition}

\begin{example}\label{eg:pairwiserelprime}
The integers $3,14,25$ are pairwise relatively prime.  Notice also
that these integers are mutually relatively prime.
\end{example}

\begin{example}\label{eg:pairwiserelprime}
Bilangan-bilangan bulat $3,14,25$ relatif prima berpasangan. Perhatikan pula
bahwa bilangan-bilangan tersebut relatif prima secara bersama-sama.
\end{example}

\begin{proposition}
For $n\in\NN$ and $a_1,\dots,a_n\in\ZZ$, if $a_1,a_2,\dots,a_n$ are pairwise
relatively prime then they are mutually relatively prime.
\end{proposition}

\begin{proposition}
Untuk $n\in\NN$ dengan $n\geq 2$ dan $a_1,\dots,a_n\in\ZZ$, jika
$a_1,a_2,\dots,a_n$ relatif prima berpasangan, maka bilangan-bilangan tersebut
relatif prima secara bersama-sama.
\end{proposition}

