\begin{discussion}
As we mentioned in the introduction, the theory of congruences was
developed by Gauss at the beginning of the nineteenth century.
\end{discussion}

\begin{discussion}
Seperti disebutkan dalam pengantar, teori kongruensi dikembangkan oleh Gauss
pada awal abad kesembilan belas.
\end{discussion}

\begin{definition}\index{congruent!definition}
Given $a,b\in\ZZ$ and $n\in\NN$, we say that {\bf $a$ is congruent to $b$
modulo $n$} if $n \mid (a-b)$, {\it i.e.,} if $\exists k\in\ZZ$ such that
$a=b+kn$.  If $a$ is congruent to $b$ modulo $n$, we write $a\equiv b\pmod{n}$.
\end{definition}

\begin{definition}\index{kongruen!definisi}
Untuk $a,b\in\ZZ$ dan $n\in\NN$, kita mengatakan bahwa {\bf $a$
kongruen dengan $b$ modulo $n$} jika $n \mid (a-b)$, yakni jika
$\exists k\in\ZZ$ sedemikian sehingga $a=b+kn$. Jika $a$ kongruen dengan
$b$ modulo $n$, kita menulis $a\equiv b\pmod{n}$.
\end{definition}

\begin{example}\label{eg:congruences}
$19\equiv 5\pmod7$.  Similarly $2k+1 \equiv 1\pmod2$ which
means every odd number is congruent to 1 modulo 2.
\end{example}

\begin{example}\label{eg:congruences}
$19\equiv 5\pmod7$. Demikian pula, $2k+1 \equiv 1\pmod2$, yang berarti
bahwa setiap bilangan ganjil kongruen dengan 1 modulo 2.
\end{example}

\begin{discussion}
Congruence is much like equality in many ways.  For example:
\end{discussion}

\begin{discussion}
Dalam banyak hal, kongruensi sangat menyerupai kesamaan. Sebagai contoh:
\end{discussion}

\begin{proof}\ 
\begin{enumerate}
\item If $a \equiv b\pmod n$, then $n\mid (a-b)$. Thus $\exists k\in\ZZ$ such
that $a-b=kn$.  This implies $b-a=(-k)n$ and thus $n\mid (b-a)$.  Consequently
$b\equiv a\pmod n$.
\item Since $a\equiv b\pmod n$ and $b\equiv c\pmod n$, $n\mid (a-b)$ and
$n\mid (b-c)$.  As a result, there $\exists k,l\in\ZZ$ such that 
$a=b+kn$ and $b=c+ln$, which imply that $a=c+(k+l)n$.  In other words,
$a=c\pmod n$.
\item Since $a\equiv b\pmod n$, $n \mid (a-b)$. So if we add and subtract $c$
we get
\begin{equation*}
n\mid ((a+c)-(b+c))
\end{equation*}
which means that
\begin{equation*}
a+c\equiv b+c\pmod n.
\end{equation*}
\item Since $a\equiv b\pmod n$, $n \mid (a-b)$ so we can subtract and add $c$
to get
\begin{equation*}
n\mid ((a-c)-(b-c))
\end{equation*}
so
\begin{equation*}
a-c\equiv b-c\pmod n.
\end{equation*}
\item If $a \equiv b\pmod n$, $n\mid (a-b)$. Thus there $\exists k\in\ZZ$ such
that $a-b=kn$ and as a result $ac-bc=(kc)n$.
Therefore
\begin{equation*}
n\mid (ac-bc)
\end{equation*}
and hence
\begin{equation*}
ac\equiv bc\pmod n.
\end{equation*}
\item If $a \equiv b\pmod n$, $n\mid (a-b)$. Thus there $\exists k\in\ZZ$ such
that $a-b=kn$ and as a result
\begin{equation*}
ac-bc=(k)cn.
\end{equation*}
Thus
\begin{equation*}
nc\mid (ac-bc)
\end{equation*}
and hence
\begin{equation*}
ac\equiv bc\pmod{nc}.
\end{equation*}
\item Since $a\equiv b\pmod n$ and $c\equiv d\pmod n$, $n\mid (a-b)$ and
$n\mid (c-d)$. As a result, there $\exists k,l\in\ZZ$ such that $a-b=kn$ and
$c-d=ln$. Note that
\begin{equation*}
(a-b)+(c-d)=(a+c)-(b+d)=(k+l)n.
\end{equation*}
As a result,
\begin{equation*}
n\mid ((a+c)-(b+d)),
\end{equation*}
hence
\begin{equation*}
a+c\equiv b+d\pmod n.
\end{equation*}
\item If $a=b+kn$ and $c=d+ln$ for $k,l\in\ZZ$, we have
\begin{equation*}
(a-b)-(c-d)=(a-c)-(b-d)=(k-l)n.
\end{equation*}
As a result,
\begin{equation*}
n\mid ((a-c)-(b-d)),
\end{equation*}
hence
\begin{equation*}
a-c\equiv b-d\pmod n.
\end{equation*}
\item $\exists k,l\in\ZZ$ such that such that $a-b=kn$ and $c-d=ln$ and thus
$ca-cb=(ck)n$ and $bc-bd=(bl)n$. Note that
\begin{equation*}
(ca-cb)+(bc-bd)=ac-bd=(kc-lb)n.
\end{equation*}
As a result,
\begin{equation*}
n\mid (ac-bd),
\end{equation*}
hence
\begin{equation*}
ac\equiv bd\pmod n.
\end{equation*}
\end{enumerate}
\end{proof}

\begin{proof}\ 
\begin{enumerate}
\item Jika $a \equiv b\pmod n$, maka $n\mid (a-b)$. Jadi terdapat
$k\in\ZZ$ sedemikian sehingga $a-b=kn$. Hal ini mengakibatkan
$b-a=(-k)n$, sehingga $n\mid (b-a)$. Dengan demikian,
$b\equiv a\pmod n$.
\item Karena $a\equiv b\pmod n$ dan $b\equiv c\pmod n$, berlaku
$n\mid (a-b)$ dan $n\mid (b-c)$. Oleh karena itu, terdapat $k,l\in\ZZ$
sedemikian sehingga $a=b+kn$ dan $b=c+ln$. Akibatnya,
$a=c+(k+l)n$. Dengan kata lain, $a\equiv c\pmod n$.
\item Karena $a\equiv b\pmod n$, berlaku $n \mid (a-b)$. Dengan
menambahkan dan mengurangkan $c$, kita memperoleh
\begin{equation*}
n\mid ((a+c)-(b+c))
\end{equation*}
yang berarti bahwa
\begin{equation*}
a+c\equiv b+c\pmod n.
\end{equation*}
\item Karena $a\equiv b\pmod n$, berlaku $n \mid (a-b)$. Dengan
mengurangkan dan menambahkan $c$, kita memperoleh
\begin{equation*}
n\mid ((a-c)-(b-c))
\end{equation*}
sehingga
\begin{equation*}
a-c\equiv b-c\pmod n.
\end{equation*}
\item Jika $a \equiv b\pmod n$, maka $n\mid (a-b)$. Jadi terdapat
$k\in\ZZ$ sedemikian sehingga $a-b=kn$, dan akibatnya
$ac-bc=(kc)n$. Oleh karena itu,
\begin{equation*}
n\mid (ac-bc)
\end{equation*}
dan dengan demikian
\begin{equation*}
ac\equiv bc\pmod n.
\end{equation*}
\item Jika $a \equiv b\pmod n$, maka $n\mid (a-b)$. Jadi terdapat
$k\in\ZZ$ sedemikian sehingga $a-b=kn$, dan akibatnya
\begin{equation*}
ac-bc=kcn.
\end{equation*}
Jadi,
\begin{equation*}
nc\mid (ac-bc)
\end{equation*}
dan dengan demikian
\begin{equation*}
ac\equiv bc\pmod{nc}.
\end{equation*}
\item Karena $a\equiv b\pmod n$ dan $c\equiv d\pmod n$, berlaku
$n\mid (a-b)$ dan $n\mid (c-d)$. Oleh karena itu, terdapat $k,l\in\ZZ$
sedemikian sehingga $a-b=kn$ dan $c-d=ln$. Perhatikan bahwa
\begin{equation*}
(a-b)+(c-d)=(a+c)-(b+d)=(k+l)n.
\end{equation*}
Akibatnya,
\begin{equation*}
n\mid ((a+c)-(b+d)),
\end{equation*}
sehingga
\begin{equation*}
a+c\equiv b+d\pmod n.
\end{equation*}
\item Jika $a=b+kn$ dan $c=d+ln$ untuk $k,l\in\ZZ$, maka
\begin{equation*}
(a-b)-(c-d)=(a-c)-(b-d)=(k-l)n.
\end{equation*}
Akibatnya,
\begin{equation*}
n\mid ((a-c)-(b-d)),
\end{equation*}
sehingga
\begin{equation*}
a-c\equiv b-d\pmod n.
\end{equation*}
\item Terdapat $k,l\in\ZZ$ sedemikian sehingga $a-b=kn$ dan $c-d=ln$.
Dengan demikian, $ca-cb=(ck)n$ dan $bc-bd=(bl)n$. Perhatikan bahwa
\begin{equation*}
(ca-cb)+(bc-bd)=ac-bd=(ck+bl)n.
\end{equation*}
Akibatnya,
\begin{equation*}
n\mid (ac-bd),
\end{equation*}
sehingga
\begin{equation*}
ac\equiv bd\pmod n.
\end{equation*}
\end{enumerate}
\end{proof}

\begin{discussion}
Here is a technical result which will be useful later:
\end{discussion}

\begin{discussion}
Berikut sebuah hasil teknis yang akan berguna kelak:
\end{discussion}

\begin{theorem}\label{thm:combing}
\index{divisibility!with relatively prime factors}
Given $a,b,c\in\ZZ$, if $a\mid c$, $b\mid c$, and $a$ and $b$ are relatively
prime, then $ab\mid c$.
\end{theorem}

\begin{theorem}\label{thm:combing}
\index{keterbagian!dengan faktor-faktor relatif prima}
Misalkan $a,b,c\in\ZZ$. Jika $a\mid c$, $b\mid c$, serta $a$ dan $b$
relatif prima, maka $ab\mid c$.
\end{theorem}

\begin{proof}
By Corollary~\ref{cor:intlincombrelprime}, we know $\exists m,n\in\ZZ$ such
that $ma+nb=1$.  Also, because of the divisibility hypotheses, we also know
$\exists p,q\in\ZZ$ such that $c=pa$ and $c=qb$.  Compute:
\begin{equation*}
c=c\cdot1=c(ma+nb)=mca+ncb=mqba+npab=(mq+np)ab\ .
\end{equation*}
But this means $ab\mid c$, as desired.
\end{proof}

\begin{proof}
Berdasarkan Akibat~\ref{cor:intlincombrelprime}, terdapat $m,n\in\ZZ$
sedemikian sehingga $ma+nb=1$. Dari hipotesis keterbagian, terdapat pula
$p,q\in\ZZ$ sedemikian sehingga $c=pa$ dan $c=qb$. Kita hitung:
\begin{equation*}
c=c\cdot1=c(ma+nb)=mca+ncb=mqba+npab=(mq+np)ab\ .
\end{equation*}
Ini berarti $ab\mid c$, seperti yang diinginkan.
\end{proof}

\begin{discussion}
Here is a result which at first seems very simple, but turns out to be
immensely useful -- so useful it has a name.
\end{discussion}

\begin{discussion}
Berikut sebuah hasil yang pada awalnya tampak sangat sederhana, tetapi ternyata
amat berguna --- sedemikian bergunanya sehingga hasil ini memiliki nama.
\end{discussion}

\begin{lemma}\label{lem:euclids}\index{Euclid's Lemma!statement}
{\bf Euclid's Lemma:}
Given $x,y,z\in\ZZ$, if $x\mid yz$ and $\gcd(x,y)=1$ then $x\mid z$.
\index{greatest common divisor!used}
\end{lemma}

\begin{lemma}\label{lem:euclids}\index{Lemma Euklides!pernyataan}
{\bf Lemma Euklides:}
Misalkan $x,y,z\in\ZZ$. Jika $x\mid yz$ dan $\gcd(x,y)=1$, maka
$x\mid z$.
\index{faktor persekutuan terbesar!digunakan}
\end{lemma}

\begin{proof}
From Corollary~\ref{cor:intlincombrelprime}, we know $\exists m,n\in\ZZ$ such
that $mx+ny=1$.  Multiplying by $z$, we get $mxz+nyz=z$.  But we've assumed
that $x\mid yz$, so $x\mid nyz$, and certainly $x\mid mxz$, so $x\mid mxz+nyz$,
{\it i.e.,} $x\mid z$.
\end{proof}

\begin{proof}
Dari Akibat~\ref{cor:intlincombrelprime}, terdapat $m,n\in\ZZ$ sedemikian
sehingga $mx+ny=1$. Dengan mengalikan kedua ruas dengan $z$, kita memperoleh
$mxz+nyz=z$. Namun, berdasarkan asumsi $x\mid yz$, berlaku $x\mid nyz$; jelas
pula bahwa $x\mid mxz$. Jadi $x\mid mxz+nyz$, yakni $x\mid z$.
\end{proof}

\begin{theorem}\ \label{thm:congcanc}
\begin{enumerate}\index{congruences!dividing both sides}
\item Given $a,b,c\in\ZZ$ and $n\in\NN$, define $d=\gcd(a,n)\in\NN$.
\index{greatest common divisor!used} If $ab\equiv ac\pmod n$ then
$b\equiv c\pmod{n/d}$.
\item In particular, if $\gcd(a,n)=1$ then\index{greatest common divisor!used}

\begin{equation*}
b=c\pmod n\qquad\Leftrightarrow\qquad ab\equiv ac\pmod n.
\end{equation*}
\end{enumerate}
\end{theorem}

\begin{theorem}\ \label{thm:congcanc}
\begin{enumerate}\index{kongruensi!membagi kedua ruas}
\item Misalkan $a,b,c\in\ZZ$ dan $n\in\NN$, serta definisikan
$d=\gcd(a,n)\in\NN$. \index{faktor persekutuan terbesar!digunakan}
Jika $ab\equiv ac\pmod n$, maka
$b\equiv c\pmod{n/d}$.
\item Secara khusus, jika $\gcd(a,n)=1$, maka
\index{faktor persekutuan terbesar!digunakan}

\begin{equation*}
b\equiv c\pmod n\qquad\Leftrightarrow\qquad ab\equiv ac\pmod n.
\end{equation*}
\end{enumerate}
\end{theorem}

\begin{proof}
Untuk Bagian 1, jika $ab\equiv ac\pmod n$, maka
\begin{equation*}
n\mid (ab-ac)=a(b-c).
\end{equation*}
Jadi terdapat $k\in\ZZ$ sedemikian sehingga $a(b-c)=kn$. Dengan membagi
kedua ruas dengan $d$, kita memperoleh $(a/d)(b-c)=k(n/d)$, atau
$(n/d)\mid (a/d)(b-c)$. Berdasarkan Teorema~\ref{thm:dividebygcd},
$\gcd(a/d,n/d)=1$. Karena itu, Lemma Euklides~\ref{lem:euclids}
\index{Lemma Euklides!digunakan} menyatakan bahwa $(n/d) \mid (b-c)$.
Dengan demikian, $b\equiv c\pmod{n/d}$.

Untuk Bagian 2, arah ${}\Rightarrow{}$ merupakan Bagian 5 dari
Teorema~\ref{thm:basiccongprops}, sedangkan arah ${}\Leftarrow{}$ merupakan
kasus khusus dari Bagian 1.
\end{proof}

\begin{example}\label{eg:solvcongs}
$38 \equiv 10\pmod7$.  Since $\gcd(2,7)=1$, we have $19\equiv 5\pmod7.$
\index{greatest common divisor!examples}
\end{example}

