\begin{definition}\index{linear congruence!definition}
Given constants $a,b\in\ZZ$ and $n\in\ZZ$, a congruence of the form
$ax\equiv b\pmod n$ where $x\in\ZZ$ is unknown is called a {\bf linear
congruence in one variable}.
\end{definition}

\begin{definition}\index{kongruensi linear!definisi}
Untuk konstanta $a,b\in\ZZ$ dan $n\in\NN$, kongruensi berbentuk
$ax\equiv b\pmod n$, dengan $x\in\ZZ$ sebagai peubah yang tidak diketahui,
disebut {\bf kongruensi linear dalam satu peubah}.
\end{definition}

\begin{discussion}
If a linear congruence has one solution, then it has infinitely many:
\end{discussion}

\begin{discussion}
Jika suatu kongruensi linear memiliki satu solusi, maka kongruensi itu memiliki
tak terhingga banyak solusi:
\end{discussion}

\begin{theorem}
Given constants $a,b\in\ZZ$, $n\in\ZZ$, and a solution $x\in\ZZ$ to the linear
congruence $ax\equiv b\pmod n$, any other $x^\prime\in\ZZ$ satisfying
$x^\prime\equiv x\pmod n$ is also a solution of the same congruence.
\end{theorem}

\begin{theorem}
Misalkan $a,b\in\ZZ$ dan $n\in\NN$ adalah konstanta, serta
$x\in\ZZ$ merupakan solusi kongruensi linear $ax\equiv b\pmod n$. Setiap
$x^\prime\in\ZZ$ lain yang memenuhi $x^\prime\equiv x\pmod n$ juga merupakan
solusi kongruensi yang sama.
\end{theorem}

