\begin{definition}
An algebraic equation whose constants and variables are all integers is called
a {\bf Diophantine equation}.\index{Diophantine equation}
\end{definition}

\begin{definition}
Persamaan polinomial dengan koefisien bilangan bulat yang solusi-solusinya
dicari dalam bilangan bulat disebut {\bf persamaan Diofantin}.
\index{persamaan Diofantin}
\end{definition}

\begin{theorem}\label{thm:basiclincongs}
\index{congruences!existence and number of solutions}
Let $a,b\in\ZZ$ and $n\in\NN$ and consider the linear congruence
\begin{equation*}
ax\equiv b\pmod n\ .
\end{equation*}
Setting $d=\gcd(a,n)$, we have\index{greatest common divisor!used}
\begin{enumerate}
\item If $d\nmid b$, then the congruence has no solutions.
\item If $d\mid b$, then  the congruence has exactly $d$ solutions which are
distinct modulo $n$.
\end{enumerate}
\end{theorem}

\begin{theorem}\label{thm:basiclincongs}
\index{kongruensi!keberadaan dan banyaknya solusi}
Misalkan $a,b\in\ZZ$ dan $n\in\NN$, dan tinjau kongruensi linear
\begin{equation*}
ax\equiv b\pmod n\ .
\end{equation*}
Dengan menetapkan $d=\gcd(a,n)$, berlaku
\index{faktor persekutuan terbesar!digunakan}
\begin{enumerate}
\item Jika $d\nmid b$, maka kongruensi tersebut tidak memiliki solusi.
\item Jika $d\mid b$, maka kongruensi tersebut memiliki tepat $d$ solusi
yang berbeda modulo $n$.
\end{enumerate}
\end{theorem}

\begin{remark}\label{rem:uniqsolnlincong}
\index{congruences!existence and number of solutions}\index{linear congruence!unique solution}
Notice that if $a\in\ZZ$ and $n\in\NN$ are relatively prime, then
$\forall b\in\ZZ$ there is a unique solution modulo $n$ to the equation
$ax\equiv b\pmod n$.
\end{remark}

\begin{remark}\label{rem:uniqsolnlincong}
\index{kongruensi!keberadaan dan banyaknya solusi}
\index{kongruensi linear!solusi tunggal}
Perhatikan bahwa jika $a\in\ZZ$ dan $n\in\NN$ relatif prima, maka untuk
setiap $b\in\ZZ$ terdapat tepat satu solusi modulo $n$ bagi kongruensi
$ax\equiv b\pmod n$.
\end{remark}

\begin{example}\label{eg:multiplesolscongs}
Let us find all the solutions of the congruence $3x\equiv 12\pmod6$.  Notice
that $\gcd(3,6)=3$ and $3\mid 12$.\index{greatest common divisor!examples}
Thus there are three incongruent solutions modulo $6$.  Using the Euclidean
Algorithm\index{Euclidean Algorithm!used} to find the solution of the
equation $3x-6y=12$ we get a solution $x_0=6$.  Thus the three incongruent
(modulo 6) solutions are given by $x_1=6\pmod6$, $x_1=6+2=2\pmod6$ and
$x_2=6+4=4\pmod6$.
\end{example}

\begin{discussion}
As we mentioned in Remark~\ref{rem:uniqsolnlincong}, the congruence
$ax\equiv b\pmod n$ for $a,b\in\ZZ$ and $n\in\NN$ has a unique (modulo $n$)
solution if $\gcd(a,n)=1$.  This will allow us to talk about
{\it modular inverses}.
\end{discussion}

\begin{discussion}
Seperti disebutkan dalam Catatan~\ref{rem:uniqsolnlincong}, kongruensi
$ax\equiv b\pmod n$ untuk $a,b\in\ZZ$ dan $n\in\NN$ memiliki solusi tunggal
modulo $n$ jika $\gcd(a,n)=1$. Hal ini memungkinkan kita membahas
{\it invers modular}.
\end{discussion}

\begin{definition}
\index{multiplicative inverse!mod $n$}
Given $a\in\ZZ$ and $n\in\NN$, a solution to the congruence
$ax\equiv 1\pmod n$ for $(a,n)=1$ is called the {\bf inverse of $a$ modulo n}.
We denote such an inverse by $a^{-1}$, with the $n$ to be understood from
context.
\end{definition}

\begin{definition}
\index{invers multiplikatif!modulo $n$}
Misalkan $a\in\ZZ$ dan $n\in\NN$ dengan $\gcd(a,n)=1$. Suatu solusi
kongruensi $ax\equiv 1\pmod n$ disebut {\bf invers $a$ modulo $n$}.
Kita menyatakan invers semacam itu dengan $a^{-1}$; nilai $n$ dipahami dari
konteks.
\end{definition}

