\begin{theorem}
\textbf{The Chinese Remainder Theorem:}\index{Chinese Remainder Theorem}
Fix a $k\in\NN$.  Then given $b_1,\dots,b_k\in\ZZ$ and $n_1,\dots,n_k\in\NN$,
the system of congruences
\begin{align*}
x&\equiv b_1\pmod{n_1}\\
x&\equiv b_2\pmod{n_2}\\
&\vdots\\
x&\equiv b_k\pmod{n_k}
\end{align*}
has a solution $x\in\ZZ$ if the $n_1,n_2,\dots,n_k$ are pairwise relatively
prime\index{pairwise relatively prime}.  The solution is unique modulo
$N=n_1\,n_2\dots n_k$.
\end{theorem}

\begin{theorem}
\textbf{Teorema Sisa Cina:}\index{Teorema Sisa Cina}
Tetapkan $k\in\NN$. Untuk $b_1,\dots,b_k\in\ZZ$ dan
$n_1,\dots,n_k\in\NN$, sistem kongruensi
\begin{align*}
x&\equiv b_1\pmod{n_1}\\
x&\equiv b_2\pmod{n_2}\\
&\vdots\\
x&\equiv b_k\pmod{n_k}
\end{align*}
memiliki solusi $x\in\ZZ$ jika $n_1,n_2,\dots,n_k$ relatif prima
berpasangan\index{relatif prima berpasangan}. Solusinya tunggal modulo
$N=n_1\,n_2\dots n_k$.
\end{theorem}

\begin{proof}
For $j=1,\dots,k$, let $N_j=N/n_j$.  Since the moduli $n_j$ are pairwise
relatively prime, $\gcd(N_j,n_j)=1$\index{greatest common divisor!used}
-- after all, $N_j$ is the product of all the moduli except $n_j$.  Hence by
Corollary \ref{cor:modinv}, $\exists y_j = N_j^{-1}$ modulo $n_j$, satisfying
$N_jy_j\equiv 1\pmod{n_j}$.
Consider now
\begin{equation*}
x=\sum_{j=1}^k b_j N_j y_j
\end{equation*}
Since
\begin{equation*}
N_j\equiv 0\pmod{n_i} \ \ \forall i\neq j,
\end{equation*}
we see that
\begin{equation*}
x\equiv b_j N_j y_j\equiv b_j\pmod{n_j}.
\end{equation*}
Hence $x$ is a solution to the system of congruences.

We have to show now that any two solutions are congruent modulo $N$.  Suppose
that $x$ and $y$ are both solutions of the system of congruences.  Then
$x\equiv b_j\equiv y\pmod{n_j}$, or $n_j\mid x-y$, for all $1\leq j\leq k$.
But then, since the moduli are pairwise relatively prime, using 
Theorem~\ref{thm:combing} $k$ times (formally, this needs to be done by
induction!), we can conclude that $N=n_1\dots n_k\mid x-y$ or
$x\equiv y\pmod N$.
\end{proof}

\begin{example}\label{eg:systemofcongs}
Solve the system
\begin{align*}
x&\equiv 1\pmod2\\
x&\equiv 2\pmod3\\
x&\equiv 3\pmod5.
\end{align*}
We have $N=2\cdot3\cdot5=30$.  Also
\begin{equation*}
N_1=30/2=15,\ N_2=30/3=10,\ \mbox{and} \  N_3=30/5=6.
\end{equation*}
So we have to solve now $15y_1\equiv 1\pmod2$ -- a solution is
$y_1\equiv 1\pmod2$.  In the same way, we find that $y_2\equiv 1\pmod3$ and
$y_3\equiv 1\pmod5$.  Therefore
\begin{equation*}
x=1\cdot15\cdot1+2\cdot10\cdot1+3\cdot6\cdot1=53\equiv 23\pmod{30}.
\end{equation*}
\end{example}

\begin{example}\label{eg:systemofcongs}
Selesaikan sistem
\begin{align*}
x&\equiv 1\pmod2\\
x&\equiv 2\pmod3\\
x&\equiv 3\pmod5.
\end{align*}
Kita memperoleh $N=2\cdot3\cdot5=30$. Selain itu,
\begin{equation*}
N_1=30/2=15,\ N_2=30/3=10,\ \mbox{dan} \  N_3=30/5=6.
\end{equation*}
Sekarang kita perlu menyelesaikan $15y_1\equiv 1\pmod2$; salah satu solusinya
adalah $y_1\equiv 1\pmod2$. Dengan cara yang sama, kita memperoleh
$y_2\equiv 1\pmod3$ dan $y_3\equiv 1\pmod5$. Oleh karena itu,
\begin{equation*}
x=1\cdot15\cdot1+2\cdot10\cdot1+3\cdot6\cdot1=53\equiv 23\pmod{30}.
\end{equation*}
\end{example}

