\begin{discussion}
In this section, we shall consider another way to work with congruences,
based upon the following:
\end{discussion}

\begin{discussion}
Dalam bagian ini, kita akan mempelajari cara lain untuk menangani kongruensi,
berdasarkan gagasan berikut.
\end{discussion}

\begin{definition}
\index{equivalence relation!definition}
Let $S$ be a set and ${}\cong{}$ a {\it relation} defined on $S$.  (That is,
$\forall x,y\in S$, the statement ``$x\cong y$'' may be true or false.)  If
${}\cong{}$ satisfies the following three properties, it is called an
{\bf equivalence relation}:
\begin{itemize}
\item {\it [Reflexivity]} $\forall x\in S$, $x\cong x$.\index{equivalence relation!reflexivity}
\item {\it [Symmetry]} $\forall x,y\in S$, $x\cong y\Leftrightarrow y\cong x$.\index{equivalence relation!symmetry}
\item {\it [Transitivity]} $\forall x,y,z\in S$, $x\cong y$ and
$y\cong z\Rightarrow x\cong z$.\index{equivalence relation!transitivity}
\end{itemize}

If ${}\cong{}$ is an equivalence relation on the set $S$ and $x\in S$, then the
set $[x]=\{y\in S\mid y\cong x\}\subseteq S$ is called the
{\bf equivalence class of $x$}\index{equivalence classes!definition}.  We write
$S/{{}\cong{}}$ for the set of equivalence classes in $S$.  And if $\Cc\in S$,
then any $r\in S$ such that $\Cc=[r]$ is called a
{\bf representative of the equivalence class $\Cc$}.\index{equivalence classes!representative}
\end{definition}

\begin{definition}
\index{relasi ekuivalensi!definisi}
Misalkan $S$ suatu himpunan dan ${}\cong{}$ suatu {\it relasi} yang didefinisikan
pada $S$. (Artinya, untuk setiap $x,y\in S$, pernyataan ``$x\cong y$'' dapat
bernilai benar atau salah.) Jika ${}\cong{}$ memenuhi ketiga sifat berikut,
relasi itu disebut {\bf relasi ekuivalensi}:
\begin{itemize}
\item {\it [Refleksivitas]} $\forall x\in S$, $x\cong x$.\index{relasi ekuivalensi!refleksivitas}
\item {\it [Simetri]} $\forall x,y\in S$, $x\cong y\Leftrightarrow y\cong x$.\index{relasi ekuivalensi!simetri}
\item {\it [Transitivitas]} $\forall x,y,z\in S$, $x\cong y$ dan
$y\cong z\Rightarrow x\cong z$.\index{relasi ekuivalensi!transitivitas}
\end{itemize}

Jika ${}\cong{}$ merupakan relasi ekuivalensi pada himpunan $S$ dan $x\in S$,
maka himpunan $[x]=\{y\in S\mid y\cong x\}\subseteq S$ disebut
{\bf kelas ekuivalensi dari $x$}\index{kelas ekuivalensi!definisi}. Kita menulis
$S/{{}\cong{}}$ untuk himpunan semua kelas ekuivalensi dalam $S$. Jika
$\Cc\in S/{{}\cong{}}$, maka setiap $r\in S$ yang memenuhi $\Cc=[r]$ disebut
{\bf wakil kelas ekuivalensi $\Cc$}.\index{kelas ekuivalensi!wakil}
\end{definition}

\begin{theorem}\index{equivalence classes!disjoint or equal}
Let $S$ be a set and ${}\cong{}$ an equivalence relation defined on $S$.  Then
\begin{enumerate}
\item $\forall x\in S,\ x\in[x]$.
\item $\forall x,y\in S$, either $[x]=[y]$ or $[x]\cap[y]=\emptyset$, but not
both.
\end{enumerate}
\end{theorem}

\begin{theorem}\index{kelas ekuivalensi!saling lepas atau sama}
Misalkan $S$ suatu himpunan dan ${}\cong{}$ suatu relasi ekuivalensi yang
didefinisikan pada $S$. Maka
\begin{enumerate}
\item $\forall x\in S,\ x\in[x]$.
\item $\forall x,y\in S$, berlaku tepat salah satu dari $[x]=[y]$ atau
$[x]\cap[y]=\emptyset$.
\end{enumerate}
\end{theorem}

\begin{example}\label{eg:rationals}\index{equivalence classes!example: $\QQ$}
On the set $S=\{(n,m)\mid n,m\in\ZZ, m\neq0\}$ we can define the relation
$(a,b)\cong(c,d)$ if $ad=cb$.  Then $S/{{}\cong{}}$ is nothing other than the
rational numbers, $\QQ$!
\end{example}

\begin{example}\label{eg:rationals}\index{kelas ekuivalensi!contoh: $\QQ$}
Pada himpunan $S=\{(n,m)\mid n,m\in\ZZ, m\neq0\}$, kita dapat mendefinisikan
relasi $(a,b)\cong(c,d)$ jika $ad=cb$. Maka $S/{{}\cong{}}$ tidak lain adalah
himpunan bilangan rasional, $\QQ$!
\end{example}

\begin{discussion}
Now let us specialize the concept of equivalence class to the case of
congruences:
\end{discussion}

\begin{discussion}
Sekarang, mari kita khususkan konsep kelas ekuivalensi pada kongruensi.
\end{discussion}

\begin{proposition}\index{equivalence classes!example: congruence classes}
Given $n\in\NN$, the relation on $\ZZ$ defined by
$$
a\cong_n b\Leftrightarrow a\equiv b\pmod{n}
$$
(which we shall write $a\cong b$ if the $n$ is clear from context) is an
equivalence relation.
\end{proposition}

\begin{proposition}\index{kelas ekuivalensi!contoh: kelas kongruensi}
Untuk $n\in\NN$, relasi pada $\ZZ$ yang didefinisikan oleh
$$
a\cong_n b\Leftrightarrow a\equiv b\pmod{n}
$$
(yang akan kita tulis sebagai $a\cong b$ jika $n$ jelas dari konteks) merupakan
relasi ekuivalensi.
\end{proposition}

\begin{definition}
Untuk $n\in\NN$ dan $a\in\ZZ$, kelas ekuivalensi dari $a$ menurut relasi
ekuivalensi di atas disebut {\bf kelas kongruensi dari $a$ modulo $n$}
\index{kelas kongruensi!definisi} dan ditulis $[a]_n$ (atau, dengan sedikit
penyalahgunaan notasi, cukup $[a]$ jika $n$ dipahami dari konteks). Himpunan
kelas ekuivalensi $\ZZ/{{}\cong_n{}}$ disebut {\bf bilangan bulat modulo $n$}
dan ditulis $\ZZ/n\ZZ$ (atau, oleh sebagian penulis, $\ZZ/n$ atau $\ZZ_n$).
\end{definition}

\begin{theorem}
\index{congruence classes!representatives}
Given $n\in\NN$, $\ZZ/n\ZZ$ has $n$ elements, with representatives
$0,\dots,n-1$ of these distinct equivalence classes.  That is,
$$
\ZZ/n\ZZ = \left\{[0]_n,\dots,[n-1]_n\right\}.
$$
\end{theorem}

\begin{theorem}
\index{kelas kongruensi!wakil}
Untuk $n\in\NN$, $\ZZ/n\ZZ$ mempunyai $n$ elemen, dengan
$0,\dots,n-1$ sebagai wakil dari kelas-kelas ekuivalensi yang berbeda itu.
Dengan kata lain,
$$
\ZZ/n\ZZ = \left\{[0]_n,\dots,[n-1]_n\right\}.
$$
\end{theorem}

\begin{discussion}
The remarkable thing about these $\ZZ/n\ZZ$ is that we can do much of the
usual integer arithmetic in them; in fact, sometimes we can do a bit more
than the usual.
\end{discussion}

\begin{discussion}
Hal menarik tentang $\ZZ/n\ZZ$ adalah bahwa kita dapat melakukan banyak
operasi aritmetika bilangan bulat yang biasa di dalamnya; bahkan, terkadang
kita dapat melakukan sedikit lebih banyak daripada biasanya.
\end{discussion}

\begin{definition}
\index{congruence classes!addition}
\index{congruence classes!multiplication}
Given $n\in\NN$ and $\Cc,\Dd\in\ZZ/n\ZZ$, define $\Cc+\Dd=[a+b]$ and
$\Cc\cdot\Dd=[a\cdot m]$ where $a$ and $b$ are any representatives of the
congruence classes $\Cc$ and $\Dd$, respectively.
\end{definition}

\begin{definition}
\index{kelas kongruensi!penjumlahan}
\index{kelas kongruensi!perkalian}
Untuk $n\in\NN$ dan $\Cc,\Dd\in\ZZ/n\ZZ$, definisikan
$\Cc+\Dd=[a+b]$ dan $\Cc\cdot\Dd=[a\cdot b]$, dengan $a$ dan $b$ masing-masing
sebarang wakil dari kelas kongruensi $\Cc$ dan $\Dd$.
\end{definition}

\begin{theorem}\label{thm:plustimeswelldefined}
The operations ${}+{}$ and ${}\cdot{}$ on $\ZZ/n\ZZ$ are well-defined.  That is,
they are independent of the choices of representatives of the congruence
classes.
\end{theorem}

\begin{theorem}\label{thm:plustimeswelldefined}
Operasi ${}+{}$ dan ${}\cdot{}$ pada $\ZZ/n\ZZ$ terdefinisi dengan baik.
Artinya, kedua operasi itu tidak bergantung pada wakil kelas kongruensi yang
dipilih.
\end{theorem}

\begin{discussion}
These new operations are quite nice:
\end{discussion}

\begin{discussion}
Operasi-operasi baru ini mempunyai sifat-sifat yang sangat baik.
\end{discussion}

\begin{theorem}\label{thm:plustimesproperties}
\index{congruence classes!addition and multiplication well-defined}
Given $n\in\NN$, the addition and multiplication on $\ZZ/n\ZZ$
\begin{enumerate}
\item are commutative and associative;
\item multiplication distributes over addition;
\item both operations have an identity -- $[0]$ for addition and $[1]$ for
  multiplication;
\item every element of $\ZZ/n\ZZ$ has an additive inverse -- the inverse of
  $[a]$ is $[-a]$ (or $[n-a]$, another name for the same thing); and
\item an element $[a]\in\ZZ/n\ZZ$ has a multiplicative inverse $[a]^{-1}$ if
and only if $\gcd(a,n)=1$;\index{greatest common divisor!used} this inverse
is unique when it exists.
\end{enumerate}
\end{theorem}

\begin{theorem}\label{thm:plustimesproperties}
\index{kelas kongruensi!penjumlahan dan perkalian terdefinisi dengan baik}
Untuk $n\in\NN$, penjumlahan dan perkalian pada $\ZZ/n\ZZ$
\begin{enumerate}
\item bersifat komutatif dan asosiatif;
\item perkalian bersifat distributif terhadap penjumlahan;
\item kedua operasi mempunyai elemen identitas, yaitu $[0]$ untuk penjumlahan
  dan $[1]$ untuk perkalian;
\item setiap elemen $\ZZ/n\ZZ$ mempunyai invers aditif, yaitu invers dari
  $[a]$ adalah $[-a]$ (atau $[n-a]$, nama lain bagi elemen yang sama); dan
\item suatu elemen $[a]\in\ZZ/n\ZZ$ mempunyai invers multiplikatif $[a]^{-1}$
jika dan hanya jika $\gcd(a,n)=1$;\index{faktor persekutuan terbesar!digunakan}
invers ini tunggal apabila ada.
\end{enumerate}
\end{theorem}

\begin{proof}
Left to the reader.  Note the last point is basically
Corollary~\ref{cor:modinv} restated in the language of congruence classes.
\end{proof}

\begin{proof}
Diserahkan kepada pembaca. Perhatikan bahwa butir terakhir pada dasarnya
merupakan Akibat~\ref{cor:modinv} yang dinyatakan kembali dalam bahasa kelas
kongruensi.
\end{proof}

\begin{discussion}
We can also restate many of our other, earlier results beside just
Corollary~\ref{cor:modinv} in terms of congruence classes.  Most of these shall
be left to the reader, but here is one example:
\end{discussion}

\begin{discussion}
Selain Akibat~\ref{cor:modinv}, banyak hasil kita sebelumnya juga dapat
dinyatakan kembali dengan kelas kongruensi. Sebagian besar akan diserahkan
