\end{discussion}

\begin{theorem}
Given $a,b\in\ZZ$ and $n\in\NN$, let $d=\gcd(a,n)$.
\index{greatest common divisor!used} Consider the equation
$$
[a]\cdot x = [b]
$$
where $x\in\ZZ/n\ZZ$.  Then
\begin{enumerate}
\item If $d\nmid b$, there are no solutions.
\item If $d\mid b$, this equation has exactly $d$ solutions in $\ZZ/n\ZZ$.
\end{enumerate}
\end{theorem}

\begin{theorem}
Untuk $a,b\in\ZZ$ dan $n\in\NN$, misalkan $d=\gcd(a,n)$.
\index{faktor persekutuan terbesar!digunakan} Tinjau persamaan
$$
[a]\cdot x = [b]
$$
dengan $x\in\ZZ/n\ZZ$. Maka
\begin{enumerate}
\item Jika $d\nmid b$, persamaan itu tidak mempunyai solusi.
\item Jika $d\mid b$, persamaan itu mempunyai tepat $d$ solusi dalam
$\ZZ/n\ZZ$.
\end{enumerate}
\end{theorem}

\begin{proof}
Left to the reader; this is really just Theorem~\ref{thm:basiclincongs}
stated differently.
\end{proof}

\begin{proof}
Diserahkan kepada pembaca; pernyataan ini tidak lain adalah
Teorema~\ref{thm:basiclincongs} dalam bentuk lain.
\end{proof}

