\begin{discussion}
Euler made the following definition, and it was good.
\end{discussion}

\begin{discussion}
Euler membuat definisi berikut, dan definisi itu ternyata sangat berguna.
\end{discussion}

\begin{definition}
\index{Euler's $\phi$/totient function!definition}
Given $n\in\NN$,
$$
\phi(n)=\#\left(\{m\in\ZZ\mid 0\le m<n\text{\ and\ }\gcd(m,n)=1\}\right)\ .
$$
\index{greatest common divisor!used}
In other words, $\phi(n)$ counts the number of non-negative integers less than
$n$ which are relatively prime to $n$.

This is called {\bf Euler's $\phi$ function}, or {\bf Euler's totient function}
(``totient'' rhymes with ``quotient''; this name was give to it by the English
mathematician Sylvester).
\end{definition}

\begin{definition}
\index{fungsi $\phi$/totient Euler!definisi}
Untuk $n\in\NN$,
$$
\phi(n)=\#\left(\{m\in\ZZ\mid 0\le m<n\text{\ dan\ }\gcd(m,n)=1\}\right)\ .
$$
\index{faktor persekutuan terbesar!digunakan}
Dengan kata lain, $\phi(n)$ menghitung banyaknya bilangan bulat tak-negatif
yang lebih kecil daripada $n$ dan relatif prima dengan $n$.

Fungsi ini disebut {\bf fungsi $\phi$ Euler}, atau {\bf fungsi totient Euler}.
(Dalam bahasa Inggris, ``totient'' berima dengan ``quotient''; nama ini
diberikan oleh matematikawan Inggris Sylvester.)
\end{definition}

\begin{discussion}
Here's one thing it is good for:
\end{discussion}

\begin{discussion}
Berikut salah satu kegunaan fungsi tersebut.
\end{discussion}

\begin{theorem}
\index{Euler's $\phi$/totient function!counts elements of $\left(\ZZ/n\ZZ\right)^*$}
Given $n\in\NN$, $\phi(n)$ is the number of elements of $\ZZ/n\ZZ$ which are
(multiplicatively) invertible.
\end{theorem}

\begin{theorem}
\index{fungsi $\phi$/totient Euler!menghitung elemen $\left(\ZZ/n\ZZ\right)^*$}
Untuk $n\in\NN$, $\phi(n)$ adalah banyaknya elemen $\ZZ/n\ZZ$ yang mempunyai
invers multiplikatif.
\end{theorem}

\begin{proof}
This is just Theorem~\ref{thm:plustimesproperties} part (5)
\end{proof}

\begin{proof}
Pernyataan ini langsung mengikuti Bagian (5) dari
Teorema~\ref{thm:plustimesproperties}.
\end{proof}

\begin{discussion}
One quite surprising fact about Euler's totient function is that it is
multiplicative, at least for relatively prime numbers:
\end{discussion}

\begin{discussion}
Satu fakta yang cukup mengejutkan tentang fungsi totient Euler adalah bahwa
fungsi ini bersifat multiplikatif, setidaknya untuk bilangan-bilangan yang
relatif prima.
\end{discussion}

\begin{theorem}\label{thm:phiismultiplicative}
\index{Euler's $\phi$/totient function!is multiplicative for relatively prime integers}
Given $n,m\in\ZZ$, if $\gcd(n,m)=1$\index{greatest common divisor!used}
then $\phi(nm)=\phi(n)\phi(m)$.
\end{theorem}

\begin{theorem}\label{thm:phiismultiplicative}
\index{fungsi $\phi$/totient Euler!multiplikatif untuk bilangan bulat relatif prima}
Untuk $n,m\in\NN$, jika $\gcd(n,m)=1$
\index{faktor persekutuan terbesar!digunakan}, maka
$\phi(nm)=\phi(n)\phi(m)$.
\end{theorem}

\begin{exercise}
Compute $\phi(n)$ for $n=2,3,5,7,11,13,17$.  Make a general conjecture. Can
you prove it?\index{Euler's $\phi$/totient function!values}
\end{exercise}

\begin{exercise}
Hitunglah $\phi(n)$ untuk $n=2,3,5,7,11,13,17$. Buatlah dugaan umum. Dapatkah
Anda membuktikannya?\index{fungsi $\phi$/totient Euler!nilai}
\end{exercise}

\begin{exercise}
Compute $\phi(n)$ for $n=2,4,8, 16, 32, 64$.  Make a conjecture about
$\phi(2^k)$ for $k\in\NN$.  Prove it!
\index{Euler's $\phi$/totient function!values}
\end{exercise}

\begin{exercise}
Hitunglah $\phi(n)$ untuk $n=2,4,8,16,32,64$. Buatlah dugaan tentang
$\phi(2^k)$ untuk $k\in\NN$. Buktikan dugaan tersebut!
\index{fungsi $\phi$/totient Euler!nilai}
\end{exercise}

\begin{discussion}
Primes are the atoms out of which the more complicated, composite integers (the
molecules, in this metaphor) are built.  In this chapter we study some of their
basic properties, prove the aptly named Fundamental Theorem of Arithmetic, and
go on to Wilson's Theorem.
\end{discussion}

\begin{discussion}
Bilangan prima adalah atom-atom penyusun bilangan bulat komposit yang lebih
rumit (molekul-molekul, dalam perumpamaan ini). Dalam bab ini, kita mempelajari
beberapa sifat dasarnya, membuktikan Teorema Dasar Aritmetika, lalu melanjutkan
ke Teorema Wilson.
\end{discussion}

\begin{discussion}
First of all, we make the
\end{discussion}

\begin{discussion}
Pertama-tama, kita membuat definisi berikut.
\end{discussion}

\begin{definition}\index{prime!definition}
We say $p\in\NN$ is {\bf prime} if $p>1$ and the only natural numbers which
divide $p$ are $1$ and $p$.
\end{definition}

\begin{definition}\index{bilangan prima!definisi}
Bilangan $p\in\NN$ disebut {\bf prima} jika $p>1$ dan satu-satunya bilangan
asli yang membagi $p$ adalah $1$ dan $p$.
\end{definition}

\begin{definition}\index{composite!definition}
A number $c\in\NN$ which is greater than $1$ and not prime is called
{\bf composite}.
\end{definition}

\begin{definition}\index{bilangan komposit!definisi}
Bilangan $c\in\NN$ yang lebih besar daripada $1$ dan tidak prima disebut
{\bf komposit}.
\end{definition}

\begin{discussion}
How far does a naive, brute-force check have to go in order to see if a number
is composite?
\end{discussion}

\begin{discussion}
Sejauh mana pemeriksaan langsung dengan cara kasar harus dilakukan untuk
menentukan apakah suatu bilangan komposit?
\end{discussion}

\begin{theorem}\index{composite!size of smallest factor}
If $n$ is a composite, then it has a positive divisor $d$ satisfying
$d\le\sqrt{n}$.
\end{theorem}

\begin{theorem}\index{bilangan komposit!ukuran faktor terkecil}
Jika $n$ komposit, maka $n$ mempunyai pembagi positif $d$ yang memenuhi
$d\le\sqrt{n}$.
\end{theorem}

\begin{discussion}
Euclid's Lemma (Lemma~\ref{lem:euclids}) takes a particularly nice form if the
divisor involved is prime:
\end{discussion}

\begin{discussion}
Lemma Euklides (Lemma~\ref{lem:euclids}) mempunyai bentuk yang sangat baik jika
pembagi yang terlibat merupakan bilangan prima.
\end{discussion}

\begin{proposition}\label{prop:primesdividingproducts}
\index{prime!dividing a product}
Suppose $p$ is a prime and $a,b\in\ZZ$.  If $p\mid ab$ then $p\mid $ or
$p\mid b$.
\end{proposition}

\begin{proposition}\label{prop:primesdividingproducts}
\index{bilangan prima!membagi suatu hasil kali}
Misalkan $p$ prima dan $a,b\in\ZZ$. Jika $p\mid ab$, maka $p\mid a$ atau
$p\mid b$.
\end{proposition}

\begin{discussion}
A more general form of this is
\end{discussion}

\begin{discussion}
Bentuk yang lebih umum dari hasil ini adalah sebagai berikut.
\end{discussion}

\begin{corollary}\label{cor:primedivis}
\index{prime!dividing a product}
Suppose $p$ is a prime, $k\in\NN$, and $a_1,\dots,a_k\in\ZZ$.  Then if
$p\mid a_1\dots a_k$, it follows that $p$ divides at least one of the $a_j$.
\end{corollary}

\begin{corollary}\label{cor:primedivis}
\index{bilangan prima!membagi suatu hasil kali}
Misalkan $p$ prima, $k\in\NN$, dan $a_1,\dots,a_k\in\ZZ$. Jika
$p\mid a_1\dots a_k$, maka $p$ membagi setidaknya satu dari bilangan $a_j$.
\end{corollary}

\begin{proof}
Left to the reader (use induction on $k$).
\end{proof}

\begin{proof}
Diserahkan kepada pembaca (gunakan induksi pada $k$).
\end{proof}

\begin{discussion}
This leads to the aptly named
\end{discussion}

\begin{discussion}
Hasil ini membawa kita pada teorema yang namanya sangat sesuai berikut.
\end{discussion}

\begin{theorem}
\textbf{The Fundamental Theorem of Arithmetic:}
\index{Fundamental Theorem of Arithmetic!statement}
Let $n\in\NN$, $n\ge2$.  Then $\exists k\in\NN$ and primes $p_1,\dots,p_k$ such
that $n=p_1\dots p_k$.  Furthermore, if $l\in\NN$ and $q_1,\dots,q_l$ are also
primes such that $n=q_1\dots q_l$, then $l=k$ and the factorization in terms
of the $q$'s is merely a reordering of that in term s of the $p$'s.
\end{theorem}

\begin{theorem}
\textbf{Teorema Dasar Aritmetika:}
\index{Teorema Dasar Aritmetika!pernyataan}
Misalkan $n\in\NN$, $n\ge2$. Maka terdapat $k\in\NN$ dan bilangan-bilangan
prima $p_1,\dots,p_k$ sedemikian sehingga $n=p_1\dots p_k$. Lebih lanjut,
jika $l\in\NN$ dan $q_1,\dots,q_l$ juga bilangan-bilangan prima yang memenuhi
$n=q_1\dots q_l$, maka $l=k$ dan faktorisasi dengan faktor-faktor $q$ hanya
merupakan penyusunan ulang dari faktorisasi dengan faktor-faktor $p$.
\end{theorem}

