\begin{definition}\label{def:confidentiality}
\index{confidentiality}
{\bf Confidentiality} means that only the intended recipient can extract the
content of the message -- Alice wants only Bob to get her message and not Eve,
no matter if she listens on the eavesdrop or intercepts the message as it
travels in some form from Alice to Bob.
\end{definition}

\begin{definition}\label{def:confidentiality}
\index{kerahasiaan}
{\bf Kerahasiaan} berarti hanya penerima yang dituju yang dapat memperoleh isi
pesan. Alice ingin hanya Bob yang menerima pesannya, bukan Eve, baik Eve
menguping dari bawah cucuran atap maupun mencegat pesan ketika pesan tersebut
bergerak dalam suatu bentuk dari Alice menuju Bob.
\end{definition}

\begin{definition}\label{def:integrity}
\index{integrity}
Message {\bf integrity} means that the recipient can be sure the message was
not altered -- Bob wants to know that what he gets is what Alice wrote, not what
the mischievous Eve intended to change it into.
\end{definition}

\begin{definition}\label{def:integrity}
\index{integritas}
{\bf Integritas} pesan berarti penerima dapat memastikan bahwa pesan tersebut
tidak diubah. Bob ingin mengetahui bahwa yang diterimanya adalah apa yang
ditulis Alice, bukan hasil perubahan yang dikehendaki Eve yang usil.
\end{definition}

\begin{definition}\label{def:authentication}
\index{authentication}
Sender {\bf authentication} means that the recipient can determine from the
message the identity of the sender -- Bob wants to be sure this message did
in fact originate with Alice.
\end{definition}

\begin{definition}\label{def:authentication}
\index{autentikasi}
{\bf Autentikasi} pengirim berarti penerima dapat menentukan identitas pengirim
dari pesan tersebut. Bob ingin memastikan bahwa pesan itu benar-benar berasal
dari Alice.
\end{definition}

\begin{definition}\label{def:non-repudiation}
\index{non-repudiation}
Sender {\bf non-repudiation} means that the sender should not be able to deny
sending that message -- Bob wants to be able to hold Alice to her promises.
\end{definition}

\begin{definition}\label{def:non-repudiation}
\index{nirpenyangkalan}
{\bf Nirpenyangkalan} pengirim berarti pengirim tidak dapat menyangkal bahwa ia
telah mengirim pesan tersebut. Bob ingin dapat menuntut Alice menepati janji
yang dinyatakannya.
\end{definition}

