\begin{discussion}
Before we go on, a few more technical terms:
\end{discussion}

\begin{discussion}
Sebelum melanjutkan, kita memerlukan beberapa istilah teknis lagi.
\end{discussion}

\begin{definition}
\label{def:clearplaintext}
\index{cleartext}\index{plaintext}
The message that Alice wishes to send to Bob, in its actual original (and final)
form is called the {\bf plaintext}.
\end{definition}

\begin{definition}
\label{def:clearplaintext}
\index{teks terang}\index{plainteks}
Pesan yang hendak dikirim Alice kepada Bob dalam bentuk aslinya (dan bentuk
akhir yang dipulihkan) disebut {\bf plainteks} atau {\bf teks terang}.
\end{definition}

\begin{definition}\label{def:encryptioncipher}
\index{encryption}\index{cipher}
An algorithm that Alice uses to transform (obfuscate) the plaintext into
a form that will remain confidential even if observed by Eve while in flight
is called a {\bf cipher}.  We also say that Alice {\bf encrypts} the (plaintext)
message.
\end{definition}

\begin{definition}\label{def:encryptioncipher}
\index{enkripsi}\index{cipher}
Algoritme yang digunakan Alice untuk mengubah (mengaburkan) plainteks menjadi
bentuk yang tetap rahasia sekalipun diamati Eve selama pengiriman disebut
{\bf cipher} atau algoritme sandi. Kita juga mengatakan bahwa Alice
{\bf mengenkripsi} pesan (plainteks) tersebut.
\end{definition}

\begin{definition}\label{def:ciphertext}
\index{ciphertext}
After the message has been encrypted, it is called the {\bf ciphertext}.
\end{definition}

\begin{definition}\label{def:ciphertext}
\index{cipherteks}
Setelah dienkripsi, pesan tersebut disebut {\bf cipherteks} atau
{\bf teks sandi}.
\end{definition}

\begin{definition}\label{def:decrypt}
\index{ciphertext}
When Bob receives the ciphertext, he applies another algorithm to {\bf decrypt}
it and recover the plaintext.
\end{definition}

\begin{definition}\label{def:decrypt}
\index{dekripsi}
Ketika menerima cipherteks, Bob menerapkan algoritme lain untuk
{\bf mendekripsinya} dan memulihkan plainteks.
\end{definition}

\begin{discussion}
Graphically:
\end{discussion}

\begin{discussion}
Secara grafis:
\end{discussion}

\begin{definition}\label{def:key}
\index{key}
Additional information (some of which is) used in encryption and (some of)
which is necessary for successful decryption is called a {\bf key}.
\end{definition}

\begin{definition}\label{def:key}
\index{kunci}
Informasi tambahan---sebagian digunakan dalam enkripsi dan sebagian diperlukan
agar dekripsi berhasil---disebut {\bf kunci}.
\end{definition}

\begin{exercise}
Even if the scytale cryptosystem were strong, there may be problems using it
for {\it authentication}.  Describe how authentication might fail depending
upon the message being sent -- give an example or two of ``bad'' messages for
authentication.
\end{exercise}

\begin{exercise}
Sekalipun kriptosistem scytale kuat, penggunaannya untuk {\it autentikasi}
mungkin bermasalah. Jelaskan bagaimana autentikasi dapat gagal bergantung pada
pesan yang dikirim; berikan satu atau dua contoh pesan yang ``buruk'' untuk
autentikasi.
\end{exercise}

\begin{exercise}
The scytale cryptosystem seems weak.  Describe how you would cryptanalyze it.
\end{exercise}

\begin{exercise}
Kriptosistem scytale tampak lemah. Jelaskan bagaimana Anda akan melakukan
kriptanalisis terhadapnya.
\end{exercise}

\begin{discussion}
Another system which dates to ancient times was supposedly used by Julius
Caesar.
\end{discussion}

\begin{discussion}
Sistem lain yang berasal dari zaman kuno konon digunakan oleh Julius Caesar.
\end{discussion}

\begin{definition}
\label{def:caesarcipher}
\index{Caesar cipher!definition}
Alice takes her message, removes all spaces and punctuation, and puts it all
in one case (maybe upper case).  Then she moves each letter $k$ places
down the alphabet, wrapping around from Z to A if necessary, where $k\in\ZZ$ is
a fixed number known to both Alice and Bob but no one else, called the
{\bf key}.

To decrypt, Bob simply moves each letter $k$ places earlier in the alphabet,
wrapping past A to Z if necessary: {\it i.e.} Bob encrypts the ciphertext with
key $-k$ to get the plaintext.

This is called the {\bf Caesar cryptosystem}.
\end{definition}

\begin{definition}
\label{def:caesarcipher}
\index{cipher Caesar!definisi}
Alice mengambil pesannya, menghapus semua spasi dan tanda baca, lalu menyamakan
kapitalisasi seluruh hurufnya (misalnya menjadi huruf kapital). Kemudian ia
menggeser setiap huruf sejauh $k$ posisi ke depan dalam alfabet, kembali dari Z
ke A jika perlu. Di sini $k\in\ZZ$ adalah bilangan tetap yang hanya diketahui
Alice dan Bob serta disebut {\bf kunci}.

Untuk mendekripsi, Bob cukup menggeser setiap huruf sejauh $k$ posisi ke belakang
dalam alfabet, kembali dari A ke Z jika perlu. Dengan kata lain, Bob mengenkripsi
cipherteks menggunakan kunci $-k$ untuk memperoleh plainteks.

Sistem ini disebut {\bf kriptosistem Caesar}.
\end{definition}

\begin{definition}
\label{def:onetimepad}
\index{one-time pad}
A {\bf one-time pad} is a Vigen\`ere cryptosystem in which the key is as long
as the message, chosen randomly, and never re-used.  [The key is also called
the {\it one-time pad} in this cryptosystem\footnote{Another synecdoche!}.]
\end{definition}

\begin{definition}
\label{def:onetimepad}
\index{pad sekali pakai}
{\bf Pad sekali pakai} ({\it one-time pad}) adalah kriptosistem Vigen\`ere yang
kuncinya sama panjang dengan pesan, dipilih secara acak, dan tidak pernah
digunakan kembali. [Kunci dalam kriptosistem ini juga disebut {\it pad sekali
pakai}\footnote{Sinekdoke lagi!}.]
\end{definition}

\begin{definition}\label{def:keyspace}\index{keyspace}
The set of all valid keys for some cryptosystem is called its {\bf keyspace}.
\end{definition}

\begin{definition}\label{def:keyspace}\index{ruang kunci}
Himpunan semua kunci yang sah untuk suatu kriptosistem disebut
{\bf ruang kunci}.
\end{definition}

\begin{example}\label{eg:keyspaceCaesar}
The keyspace of the Caesar cipher cryptosystem is the alphabet.
\end{example}

\begin{example}\label{eg:keyspaceCaesar}
Ruang kunci kriptosistem cipher Caesar adalah alfabetnya.
\end{example}

\begin{example}\label{eg:keyspaceOTP}
Any sequence of letters of length $M$ is a possible key (pad) for a one-time
pad encryption of a message of length $M$.  Therefore there are $N^M$ possible
one-time pads for a message of length $M$ over an alphabet of size $N$.
\end{example}

\begin{example}\label{eg:keyspaceOTP}
Setiap barisan huruf sepanjang $M$ merupakan kemungkinan kunci (pad) untuk
enkripsi pad sekali pakai atas pesan sepanjang $M$. Karena itu, terdapat $N^M$
kemungkinan pad sekali pakai untuk pesan sepanjang $M$ pada alfabet berukuran
$N$.
\end{example}

\begin{definition}\label{def:messagespace}\index{messagespace}
The set of possible messages for an encrypted communication is called the
{\bf message space}.
\end{definition}

\begin{definition}\label{def:messagespace}\index{ruang pesan}
Himpunan pesan yang mungkin dalam suatu komunikasi terenkripsi disebut
{\bf ruang pesan}.
\end{definition}

