\begin{definition}
\index{distance between frequency distributions}\index{square error}
The {\bf total square error} is a distance between two distributions $f$ and
$g$ given by
$$
d(f,g)=\sum_{j=0}^{25} \left(f(j)-g(j)\right)^2
$$
where we are always working with our distributions defined on the letters in
the form `a'=0, `b'=1, {\it etc.}).
\end{definition}

\begin{definition}
\index{jarak antara distribusi frekuensi}\index{galat kuadrat}
{\bf Galat kuadrat total} adalah jarak antara dua distribusi $f$ dan $g$ yang
diberikan oleh
$$
d(f,g)=\sum_{j=0}^{25} \left(f(j)-g(j)\right)^2
$$
di mana distribusi selalu didefinisikan pada huruf dalam bentuk
`a'=0, `b'=1, dan seterusnya.
\end{definition}

