\begin{definition}
{\bf Cryptographic salt} is random data added to a message Alice desires to
send to Bob before she encrypts it, which is automatically removed at Bob's
end.
\end{definition}

\begin{definition}
{\bf Salt kriptografis} adalah data acak yang ditambahkan pada pesan yang hendak
dikirim Alice kepada Bob sebelum dienkripsi, lalu dihapus secara otomatis di
sisi Bob.
\end{definition}

\begin{definition}\label{def:onewayfcn}\index{one-way function}
A function $f:A\to B$ which is one-to-one and which can be computed in a
reasonable amount of time on a standard (classical) computer but whose inverse
cannot feasibly be computed is called a [{\bf cryptographic}]
{\bf one-way function}.
\end{definition}

\begin{definition}\label{def:onewayfcn}\index{fungsi satu arah}
Fungsi injektif $f:A\to B$ yang dapat dihitung dalam waktu wajar pada komputer
standar (klasik), tetapi inversnya tidak dapat dihitung secara layak, disebut
{\bf fungsi satu arah} [atau {\bf fungsi satu arah kriptografis}].
\end{definition}

