\begin{theorem}\label{thm:noPRspowersoftwo}
Let $k\in\NN$ satisfy $n\ge3$.  Then $n=2^k$ has no primitive roots.
\end{theorem}

\begin{theorem}\label{thm:noPRspowersoftwo}
Misalkan $k\in\NN$ memenuhi $k\ge3$. Maka $2^k$ tidak mempunyai akar primitif.
\end{theorem}

