\begin{definition}\label{def:index}\index{index!definition}
If $n\in\NN$ has a primitive root $a$, then for any $b\in\ZZ$ such that
$\gcd(b,n)=1$\index{greatest common divisor!used} the smallest $k\in\NN$ such
that $b\equiv a^k\pmod{n}$ is called the {\bf index of $b$ relative to $a$}
and is denoted $\ind_a(b)$.
We shall also sometimes talk about $\ind_a(x)$ where $x\in(\ZZ/n\ZZ)^*$, meaning
the index relative to $a$ of any representative $b$ of the congruence class $x$.
\end{definition}

\begin{discussion}
Some things are natural to conjecture, given these examples and the simple
definition of index; many of them are very easy to prove (and are exercises):
\end{discussion}

\begin{discussion}
Berdasarkan contoh-contoh dan definisi indeks yang sederhana ini, beberapa
dugaan muncul secara alami. Banyak di antaranya sangat mudah dibuktikan (dan
dijadikan latihan):
\end{discussion}

\begin{theorem}\label{thm:indexprops}\index{index!basic properties}
Let $n\in\NN$ have a primitive root $a$.  Then
\begin{enumerate}
\item $\ind_a(1)=\ord_n(a)=\phi(n)$; equivalently,
$\ind_a(1)\equiv0\pmod{\phi(n)}$
\item $\ind_a(a)=1$
\item $\forall b,c\in\ZZ$ such that
$\gcd(b,n)=\gcd(c,n)=1$,\index{greatest common divisor!used} we have
$$
\ind_a(bc)\equiv\ind_a(b)+\ind_a(c)\pmod{\phi(n)}
$$
\item $\forall b\in\ZZ$ such that $\gcd(b,n)=1$ and $\forall k\in\NN$, we have
$$
\ind_a(b^k)\equiv k\cdot\ind_a(b)\pmod{\phi(n)}
$$
\end{enumerate}
\end{theorem}

\begin{theorem}\label{thm:indexprops}\index{indeks!sifat dasar}
Misalkan $n\in\NN$ mempunyai akar primitif $a$. Maka
\begin{enumerate}
\item $\ind_a(1)=\ord_n(a)=\phi(n)$; secara ekuivalen,
$\ind_a(1)\equiv0\pmod{\phi(n)}$;
\item $\ind_a(a)=1$;
\item untuk setiap $b,c\in\ZZ$ yang memenuhi
$\gcd(b,n)=\gcd(c,n)=1$,\index{faktor persekutuan terbesar!digunakan} berlaku
$$
\ind_a(bc)\equiv\ind_a(b)+\ind_a(c)\pmod{\phi(n)}
$$
\item untuk setiap $b\in\ZZ$ dengan $\gcd(b,n)=1$ dan setiap $k\in\NN$,
berlaku
$$
\ind_a(b^k)\equiv k\cdot\ind_a(b)\pmod{\phi(n)}
$$
\end{enumerate}
\end{theorem}

