\begin{proposition}\label{prop:DHKEworks}
When Alice and Bob follow the DHKE protocol, they both compute the same
shared key; \emph{i.e., DHKE works}.
\end{proposition}

\begin{proposition}\label{prop:DHKEworks}
Jika Alice dan Bob mengikuti protokol DHKE, keduanya menghitung kunci bersama
yang sama; \emph{dengan kata lain, DHKE berfungsi}.
\end{proposition}

\begin{definition}\label{def:SGprime}\index{Sophie Germain prime!definition}
A prime $p$ with the property that $2p+1$ is also a prime is called a
{\bf Sophie Germain prime}.
\end{definition}

\begin{definition}\label{def:SGprime}\index{prima Sophie Germain!definisi}
Bilangan prima $p$ yang membuat $2p+1$ juga prima disebut
{\bf prima Sophie Germain}.
\end{definition}

\begin{discussion}

It is not known how many Sophie Germain primes there are, although it is
conjectured that there are an infinite number.  In fact, there are precise
conjectures on the asymptotic density of such primes, as well as algorithmic
techniques to generate them efficiently; see \cite{shoup2009computational}.
\end{discussion}

\begin{discussion}

Belum diketahui berapa banyak prima Sophie Germain yang ada, meskipun diduga
jumlahnya tak hingga. Bahkan, terdapat dugaan yang cermat mengenai kepadatan
asimtotik prima semacam itu serta teknik algoritmik untuk membangkitkannya
secara efisien; lihat \cite{shoup2009computational}.
\end{discussion}

\begin{example}\index{Sophie Germain prime!examples}
The first seventeen Sophie Germain primes are
\begin{center}
$2,\ 3,\ 5,\ 11,\ 23,\ 29,\ 41,\ 53,\ 83,\ 89,\ 113,\ 131,\ 173,\ 179,\ 191,\ 
233,\ 239$
\end{center}
The sequence of all Sophie Germain primes is sequence {\it A005384} at the
{\it On-Line Encyclopedia of Integer Sequences}, {\tt oeis.org}.

The largest known Sophie Germain prime, at the time of this writing, is
\begin{center}
$18543637900515\times2^{666667}-1$
\end{center}
discovered in 2012 by Philipp Bliedung and a large distributed network of
computers.
\end{example}

\begin{example}\index{prima Sophie Germain!contoh}
Tujuh belas prima Sophie Germain pertama ialah
\begin{center}
$2,\ 3,\ 5,\ 11,\ 23,\ 29,\ 41,\ 53,\ 83,\ 89,\ 113,\ 131,\ 173,\ 179,\ 191,\ 
233,\ 239$
\end{center}
Barisan semua prima Sophie Germain adalah barisan {\it A005384} dalam
{\it On-Line Encyclopedia of Integer Sequences}, {\tt oeis.org}.

Pada saat naskah sumber ini ditulis, prima Sophie Germain terbesar yang
diketahui ialah
\begin{center}
$18543637900515\times2^{666667}-1$
\end{center}
yang ditemukan pada 2012 oleh Philipp Bliedung dan sebuah jaringan besar
komputer terdistribusi.
\end{example}

\begin{definition}\label{def:DHproblem}\index{Diffie-Hellman problem}
The {\bf Diffie-Hellman problem} [{\bf DHP}] consists of the following
question:  Given
\begin{itemize}
\item a prime $p$,
\item a primitive root $r\in(\ZZ/p\ZZ)^*$, and
\item two elements $a,b\in(\ZZ/p\ZZ)^*$ which are known to be of the
form $a=r^x$ and $b=r^y$ for $x,y\in\NN$, although the $x$ and $y$ are not
known
\end{itemize}
compute
\begin{itemize}
\item $r^{xy}$\ .
\end{itemize}
\end{definition}

\begin{definition}\label{def:DHproblem}\index{masalah Diffie--Hellman}
{\bf Masalah Diffie--Hellman} [{\bf DHP}] adalah pertanyaan berikut. Diberikan
\begin{itemize}
\item bilangan prima $p$,
\item akar primitif $r\in(\ZZ/p\ZZ)^*$, dan
\item dua unsur $a,b\in(\ZZ/p\ZZ)^*$ yang diketahui berbentuk $a=r^x$ dan
$b=r^y$ untuk $x,y\in\NN$, meskipun $x$ dan $y$ tidak diketahui,
\end{itemize}
hitung
\begin{itemize}
\item $r^{xy}$\ .
\end{itemize}
\end{definition}

